-- Aimchess — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aimchess.com' OR LOWER(`name`) = LOWER('Aimchess'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Aimchess', NULL, 'https://aimchess.com', NULL, NULL, 'Aimchess — шаховий тренер на основі аналітики: аналізує кожен хід ваших недавніх партій, оцінює шість ключових навичок, показує, що заважає рости (наприклад, контроль часу), і створює уроки з ваших партій.', 'Aimchess is an analytics-based chess coach: it analyzes every move of your recent games, measures six core skills, shows what holds you back (such as time management) and builds lessons from your games.', 'Aimchess допомагає шахістам прогресувати швидше, поєднуючи унікальну аналітику з персональними уроками, створеними з ваших власних партій. Після реєстрації сервіс аналізує кожен хід недавніх ігор і вимірює ваш набір навичок за шістьма ключовими напрямами. Ви отримуєте прості й зрозумілі висновки, наприклад що варто попрацювати над контролем часу, бо ви відстаєте на годиннику в більшості ходів. Так видно, що саме заважає досягти піку. Уроки побудовані на ваших помилках, тому тренування стає цікавим і цілеспрямованим. Є окремі можливості для тренерів, які працюють з учнями, а також тарифи на сайті.', 'Aimchess helps chess players improve faster by combining unique analytics with personalized lessons created from your own games. After you sign up, it analyzes every move of your recent games and measures your skill set across six core areas. You get simple, clear insights — for example, that you should work on time management because you are behind on the clock for most of your moves. That shows exactly what is keeping you from your peak. Lessons are built on your mistakes, making training fun and focused. There are features for coaches working with students, and pricing is on the site.', 'Аналіз кожного ходу партій
Оцінка шести ключових навичок
Персональні уроки з ваших ігор
Поради щодо контролю часу
Інструменти для тренерів', 'Analysis of every move
Six core skill measurements
Personal lessons from your games
Time management insights
Tools for coaches', 'Шахісти-аматори, які хочуть прогресувати, і шахові тренери.', 'Amateur chess players who want to improve, and chess coaches.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aimchess.com' OR LOWER(`name`) = LOWER('Aimchess')) ORDER BY `id` LIMIT 1);
