INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Aimchess is an analytics-based chess coach: it analyzes every move of your recent games, measures six core skills, shows what holds you back (such as time management) and builds lessons from your games.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Aimchess helps chess players improve faster by combining unique analytics with personalized lessons created from your own games. After you sign up, it analyzes every move of your recent games and measures your skill set across six core areas. You get simple, clear insights — for example, that you should work on time management because you are behind on the clock for most of your moves. That shows exactly what is keeping you from your peak. Lessons are built on your mistakes, making training fun and focused. There are features for coaches working with students, and pricing is on the site.', 'manual' FROM DUAL WHERE @new = 1;
