-- Aimlabs — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aimlabs.com' OR LOWER(`name`) = LOWER('Aimlabs'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Aimlabs', NULL, 'https://aimlabs.com', NULL, NULL, 'Aimlabs — тренажер прицілювання для кіберспортсменів з AI: персональні завдання, аналітика в реальному часі, AI-коуч, 50 000+ завдань і плейлистів, профілі для 500 FPS-ігор; офіційний партнер Valorant і Rainbow Six Siege.', 'Aimlabs is an AI-powered aim trainer for esports players: personalized tasks, real-time analytics, an AI coach, 50,000+ tasks and playlists, profiles for 500 FPS games; official partner of Valorant and Rainbow Six Siege.', 'Aimlabs допомагає гравцям у шутери від першої особи покращувати навички. Тренажер пропонує AI-персоналізовані завдання, аналітику прогресу в реальному часі, мультиплеєрні змагання та інструменти під конкретні ігри. У бібліотеці понад 50 000 завдань і плейлистів, профілі для 500 FPS-ігор, AI-коуч і аналіз прицілювання з персональними порадами. Aimlabs є офіційним партнером Valorant і Rainbow Six Siege. Його створили люди, які люблять ігри, а серед команди є нейронауковці, дизайнери й розробники. Версія 2.0 вже доступна; грати можна безплатно, а PRO-членство відкриває додаткові можливості. Також є таблиці лідерів, конвертер чутливості миші та статті.', 'Aimlabs helps first-person shooter players improve their skills. The trainer offers AI-personalized tasks, real-time progress analytics, multiplayer competition and game-specific tools. The library has 50,000+ tasks and playlists, profiles for 500 FPS games, an AI coach and aim analysis with tailored tips. Aimlabs is an official partner of Valorant and Rainbow Six Siege. It was built by people who love gaming, including neuroscientists, designers and developers. Version 2.0 is out; you can play for free, and a PRO membership unlocks more features. There are also leaderboards, a mouse sensitivity converter and articles.', '50 000+ завдань і плейлистів
AI-коуч і аналіз прицілювання
Профілі для 500 FPS-ігор
Аналітика в реальному часі
Мультиплеєр
Конвертер чутливості', '50,000+ tasks and playlists
AI coach and aim analysis
Profiles for 500 FPS games
Real-time analytics
Multiplayer
Sensitivity converter', 'Гравці в шутери та кіберспортсмени, які хочуть тренувати точність і реакцію.', 'Shooter players and esports athletes who want to train accuracy and reaction.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
