-- ALTIS — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'altis.world' OR LOWER(`name`) = LOWER('ALTIS'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ALTIS', NULL, 'https://altis.world', NULL, NULL, 'ALTIS — освіта для тренерів від тренерів-призерів Олімпійських ігор: курси Need for Speed, Foundation і Performance Therapy, Speed Summit, магістерська програма, курс «Тренерське око» з Деном Пфаффом і безплатні ресурси.', 'ALTIS offers coach education from Olympic medal-winning coaches: Need for Speed, Foundation and Performance Therapy courses, the Speed Summit, an MSc program, The Coaching Eye with Dan Pfaff and free resources.', 'ALTIS допомагає тренерам вийти на новий рівень кар''єри завдяки курсам, менторству й ресурсам від тренерів, чиї спортсмени здобували олімпійські медалі. Освітні програми включають набір ALTIS Performance Trinity — курси Need for Speed, Foundation та Performance Therapy, — майстеркласи з терапії продуктивності, цифрові пакети Speed Summit, курс «Тренерське око» з Деном Пфаффом і магістерську програму ALTIS MSc. Для легкої атлетики є короткі курси на кшталт контролю дихання, роботи з фасціями та розбору техніки спринтерів. Безплатно доступні відеосерія про повернення до спринту, email-курси, електронні книги, відеогіди, статті та подкаст.', 'ALTIS helps coaches take their careers to the next level with courses, mentorships and resources from coaches whose athletes have won Olympic medals. Education includes the ALTIS Performance Trinity — the Need for Speed, Foundation and Performance Therapy courses — Performance Therapy masterclasses, Speed Summit digital packages, The Coaching Eye with Dan Pfaff and the ALTIS MSc program. For track and field there are short courses on topics such as breath control, fascia and sprint technique breakdowns. Free resources include a return-to-sprinting video series, email courses, ebooks, video guides, articles and a podcast.', 'Курси Need for Speed і Foundation
Терапія продуктивності
Speed Summit
Курс «Тренерське око»
Магістерська програма
Безплатні ресурси й подкаст', 'Need for Speed and Foundation courses
Performance therapy
Speed Summit
The Coaching Eye course
MSc program
Free resources and podcast', 'Тренери з легкої атлетики й фізпідготовки, фахівці з терапії продуктивності.', 'Track and field and strength coaches, performance therapy specialists.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
