INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'ALTIS helps coaches take their careers to the next level with courses, mentorships and resources from coaches whose athletes have won Olympic medals. Education includes the ALTIS Performance Trinity — the Need for Speed, Foundation and Performance Therapy courses — Performance Therapy masterclasses, Speed Summit digital packages, The Coaching Eye with Dan Pfaff and the ALTIS MSc program. For track and field there are short courses on topics such as breath control, fascia and sprint technique breakdowns. Free resources include a return-to-sprinting video series, email courses, ebooks, video guides, articles and a podcast.', 'manual' FROM DUAL WHERE @new = 1;
