INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Arbiter', NULL, 'https://arbiter.io', NULL, NULL, 'Arbiter (ArbiterSports) — ПЗ для шкільного спорту й заходів у США: реєстрація учнів, перевірка допуску, розклад ігор, призначення суддів, оплати, планування об''єктів і сайти без подвійного введення даних.', 'Arbiter (ArbiterSports) is US K-12 sports and activities software: student registration, eligibility, game scheduling, official assigning, payments, facility scheduling and websites with no double data entry.', 'Arbiter спрощує організацію шкільного спорту та позакласних заходів в одній платформі. Модулі включають реєстрацію учнів, перевірку їхнього допуску до змагань, розклад подій та ігор, рішення для призначення суддів і працівників заходів, платежі, планувальник спортивних об''єктів, Arbiter360 і створення спортивних сайтів. Дані не потрібно вводити двічі. Рішення розраховане на школи, асоціації, що призначають суддів, і керівні органи, а також на самих суддів, працівників заходів, адміністраторів реєстрації та родини. На сайті є кейси, блог, калькулятор заощадженого часу, відповіді на запитання та центр допомоги.', 'Arbiter simplifies K-12 sports and activities in one platform. Modules include student registration, eligibility checks, event and game scheduling, assigning solutions for officials and event workers, payments, a facilities scheduler, Arbiter360 and athletic websites. Data never need to be entered twice. It is built for schools, assigning associations and governing bodies, as well as officials, event workers, registration admins and families. The site has case studies, a blog, a time savings calculator, FAQs and a help center.', 'Реєстрація учнів і перевірка допуску
