SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'arboxapp.com' OR LOWER(`name`) = LOWER('Arbox'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Arbox', NULL, 'https://www.arboxapp.com', NULL, NULL, 'Arbox — універсальне ПЗ для малого фітнес- і велнес-бізнесу: розклад з будь-якого пристрою, оплати в застосунку й у закладі, CRM з автоматизацією продажів і маркетингу, клієнтський застосунок і звіти.', 'Arbox is all-in-one software for small fitness and wellness businesses: scheduling from any device, in-app and in-store payments, a CRM with sales and marketing automation, a client app and reporting.', 'Arbox допомагає власникам невеликих студій і залів керувати всім з однієї системи. Розклад можна організувати з будь-якого пристрою, а операційний модуль допомагає контролювати час, команду, дохід і клієнтів. Інструменти продажів і маркетингу допомагають збільшувати продажі, будувати стосунки й утримувати клієнтів, а професійна CRM автоматизує взаємодію. Оплати проходять безпечно в застосунку й у закладі. Звіти й аналітика допомагають ухвалювати рішення на основі даних. Клієнти бронюють і оплачують послуги через застосунок або за посиланнями на розклад і магазин. Arbox підходить для йоги, пілатесу, кросфіт-боксів, боксу й MMA, сайклу, а також для спа, масажу, нутриціологів і фізіотерапевтів.', 'Arbox helps owners of small studios and gyms manage everything in one system. You can organize the schedule from any device, and the operations module helps manage time, team, revenue and clients. Sales and marketing tools help boost sales, build relationships and keep clients engaged, while a professional CRM automates interactions. Payments are processed securely in the app and in store. Reporting and analytics support data-driven decisions. Clients book and pay through the app or via schedule and shop links. Arbox suits yoga, Pilates, CrossFit boxes, boxing and MMA, spinning, as well as spas, massage, nutritionists and physiotherapists.', 'Розклад і бронювання
Оплати в застосунку й у закладі
CRM з автоматизацією
Клієнтський застосунок
Звіти й аналітика
Інтеграції', 'Scheduling and booking
In-app and in-store payments
CRM with automation
Client app
Reporting and analytics
Integrations', 'Невеликі фітнес-студії, кросфіт-бокси, зали єдиноборств і велнес-фахівці.', 'Small fitness studios, CrossFit boxes, combat sports gyms and wellness practitioners.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
