SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'blitz.gg' OR LOWER(`name`) = LOWER('Blitz'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Blitz', NULL, 'https://blitz.gg', NULL, NULL, 'Blitz — ігровий помічник з оверлеями в грі, персональною статистикою й аналітикою меті на основі мільярдів матчів для League of Legends, TFT, VALORANT, CS2, Fortnite, Apex Legends, Marvel Rivals, Deadlock та інших.', 'Blitz is a gaming companion with in-game overlays, personalized stats and meta insights built on billions of matches for League of Legends, TFT, VALORANT, CS2, Fortnite, Apex Legends, Marvel Rivals, Deadlock and more.', 'Blitz допомагає гравцям краще розуміти гру й ухвалювати рішення під час матчу. Застосунок показує оверлеї прямо в грі, персональну статистику та аналітику меті, побудовану на мільярдах проаналізованих матчів. Підтримуються League of Legends, Teamfight Tactics, VALORANT, Counter-Strike 2, Fortnite, Escape From Tarkov, Apex Legends, Marvel Rivals і Deadlock. На сайті є таблиці сильних персонажів і збірок, новини й оновлення, зокрема поради з економіки в TFT. Розробники наголошують, що застосунок повністю відповідає правилам ігор. Базові функції безплатні, а Premium прибирає рекламу й додає можливості; десктопний застосунок завантажується з сайту.', 'Blitz helps players understand the game better and make decisions during a match. The app shows overlays right in the game, personalized stats and meta insights built on billions of analyzed matches. Supported games include League of Legends, Teamfight Tactics, VALORANT, Counter-Strike 2, Fortnite, Escape From Tarkov, Apex Legends, Marvel Rivals and Deadlock. The site has tier lists for champions and builds, news and updates, including TFT economy tips. The developers stress that the app is fully compliant with game rules. Core features are free, while Premium removes ads and adds more; the desktop app is downloaded from the site.', 'Оверлеї в грі
Персональна статистика
Аналітика меті з мільярдів матчів
LoL, TFT, VALORANT, CS2, Fortnite та інші
