SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'chess.com' OR LOWER(`name`) = LOWER('Chess.com'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Chess.com', NULL, 'https://www.chess.com', NULL, NULL, 'Chess.com — шахова платформа для гри онлайн із друзями й суперниками з усього світу: короткі уроки для всіх рівнів, боти з різними характерами й силою гри, тисячі задач, трансляції подій і спільнота. Є підписка.', 'Chess.com is a chess platform for playing online with friends and opponents worldwide: quick lessons for all levels, bots with distinct personalities and strengths, thousands of puzzles, live events and a community.', 'Chess.com дозволяє грати в шахи онлайн безплатно — з друзями або з суперниками з усього світу. Для навчання є короткі цікаві уроки, розраховані на гравців будь-якого рівня. Боти з унікальними характерами й різним рівнем і стилем гри дозволяють тренуватися проти комп''ютера. Тисячі шахових задач допомагають відточувати тактику й покращувати гру. Можна дивитися наживо, як змагаються найсильніші гравці світу, і стежити за подіями. Розділи «Грати», «Задачі», «Навчання», «Тренування», «Перегляд» і «Спільнота» зібрано в одному місці. Базова гра безплатна, а розширені можливості доступні за підпискою.', 'Chess.com lets you play chess online for free — with friends or opponents from around the world. For learning there are quick, fun lessons designed for players of all levels. Bots with unique personalities, skill levels and playstyles let you practice against the computer. Thousands of puzzles help sharpen tactics and improve your game. You can watch the world''s strongest players compete live and follow events. Play, Puzzles, Learn, Train, Watch and Community sections are all in one place. Basic play is free, and advanced features come with a subscription.', 'Гра онлайн безплатно
Уроки для всіх рівнів
Боти з різними характерами
Тисячі задач
Трансляції турнірів
Спільнота', 'Free online play
Lessons for all levels
Bots with personalities
Thousands of puzzles
Live event broadcasts
Community', 'Шахісти будь-якого рівня, від новачків до досвідчених.', 'Chess players of any level, from beginners to experienced.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
