SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'chessable.com' OR LOWER(`name`) = LOWER('Chessable'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Chessable', NULL, 'https://www.chessable.com', NULL, NULL, 'Chessable — застосунок для вивчення шахів з науково обґрунтованими методами запам''ятовування: понад 1000 курсів із дебютів, тактики, стратегії й ендшпілю від 400+ авторів, зокрема Магнуса Карлсена й Юдіт Полгар.', 'Chessable is a chess learning app with science-backed memorization methods: 1,000+ courses on openings, tactics, strategy and endgames from 400+ authors, including Magnus Carlsen and Judit Polgar.', 'Chessable допомагає ніколи не забувати дебюти завдяки науково обґрунтованим технікам навчання, які, за даними сервісу, суттєво підвищують запам''ятовування. Ви вивчаєте варіанти, робите запропоновані ходи, а згодом застосунок перевіряє, чи ви їх пам''ятаєте, використовуючи інтервальні повторення. Каталог містить понад 1000 курсів від більш ніж 400 авторів — від доступних тренерів до колишніх чемпіонів світу; серед інструкторів Магнус Карлсен, Юдіт Полгар, Аніш Гірі, Хікару Накамура, Фабіано Каруана та Леві Розман. Курси охоплюють дебюти, тактику, стратегію й ендшпіль для будь-якого рівня. Почати навчання можна безплатно.', 'Chessable helps you never forget your openings thanks to science-backed learning techniques that, according to the service, greatly boost retention. You study lines, make the suggested moves, and later the app quizzes you using spaced repetition. The catalog has 1,000+ courses from 400+ authors — from down-to-earth coaches to former world champions; instructors include Magnus Carlsen, Judit Polgar, Anish Giri, Hikaru Nakamura, Fabiano Caruana and Levy Rozman. Courses cover openings, tactics, strategy and endgames for every level. You can start learning for free.', 'Інтервальні повторення для запам''ятовування
1000+ шахових курсів
400+ авторів, зокрема чемпіони світу
Дебюти, тактика, стратегія, ендшпіль
Безплатний старт', 'Spaced repetition for retention
1,000+ chess courses
400+ authors, incl. world champions
Openings, tactics, strategy, endgames
Free to start', 'Шахісти будь-якого рівня, які хочуть системно вивчати теорію.', 'Chess players of any level who want to study theory systematically.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
