INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Chessable helps you never forget your openings thanks to science-backed learning techniques that, according to the service, greatly boost retention. You study lines, make the suggested moves, and later the app quizzes you using spaced repetition. The catalog has 1,000+ courses from 400+ authors — from down-to-earth coaches to former world champions; instructors include Magnus Carlsen, Judit Polgar, Anish Giri, Hikaru Nakamura, Fabiano Caruana and Levy Rozman. Courses cover openings, tactics, strategy and endgames for every level. You can start learning for free.', 'manual' FROM DUAL WHERE @new = 1;
