SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'chessify.me' OR LOWER(`name`) = LOWER('Chessify'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Chessify', NULL, 'https://chessify.me', NULL, NULL, 'Chessify — хмарна платформа для аналізу шахів рушіями: Stockfish 19 на турбошвидкостях, GPU-сервер для LCZero, база понад 9,7 млн партій з щотижневим оновленням, база ICCF, відеопошук, плагін ChessBase і застосунки.', 'Chessify is a cloud platform for chess engine analysis: Stockfish 19 at turbo speeds, a GPU server for LCZero, a 9.7M+ game database updated weekly, an ICCF database, video search, a ChessBase plugin and apps.', 'Chessify допомагає готуватися до партій за допомогою хмарних шахових рушіїв. Платформа дозволяє аналізувати позиції з Stockfish 19 і Stockfish 18 на дуже високих швидкостях, використовувати GPU-сервер для нейромережевого рушія LCZero та інші рушії, досліджувати дебюти в базі з понад 9,7 мільйона партій, що оновлюється щотижня, та в базі заочних партій ICCF. Є таблиці Syzygy для ендшпілю, відеопошук, хмарне сховище PGN, плагін для ChessBase, помічник ChessAI Buddy і застосунки для iOS та Android. Почати можна безплатно без картки, а платні плани відрізняються кількістю потоків, обсягом сховища й доступом до GPU-сервера.', 'Chessify helps you prepare for games with cloud chess engines. The platform lets you analyze positions with Stockfish 19 and Stockfish 18 at very high speeds, use a GPU server for the LCZero neural network engine and other engines, and explore openings in a database of 9.7M+ games updated weekly and in the ICCF correspondence database. There are Syzygy tablebases for endgames, video search, PGN cloud storage, a ChessBase plugin, the ChessAI Buddy assistant and iOS and Android apps. You can start free with no card, and paid plans differ by thread count, storage and GPU server access.', 'Хмарний аналіз зі Stockfish 19
GPU-сервер для LCZero
База понад 9,7 млн партій
База ICCF і таблиці Syzygy
Плагін ChessBase
iOS, Android і веб', 'Cloud analysis with Stockfish 19
GPU server for LCZero
9.7M+ game database
ICCF database and Syzygy tablebases
ChessBase plugin
iOS, Android and web', 'Шахісти, що готуються до турнірів, тренери й гросмейстери.', 'Tournament chess players, coaches and grandmasters.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
