SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'chessmood.com' OR LOWER(`name`) = LOWER('ChessMood'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ChessMood', NULL, 'https://chessmood.com', NULL, NULL, 'ChessMood — структурована система вдосконалення в шахах від гросмейстерів: понад 500 годин курсів, AI-тренер аналізує ваші партії й складає персональний план навчання, живі заходи й щоденні задачі. Є 30 днів гарантії.', 'ChessMood is a structured chess improvement system by grandmasters: 500+ hours of courses, an AI coach that analyzes your games and builds a personal study plan, live events and daily puzzles.', 'ChessMood пропонує замість хаотичного стрибання між випадковими матеріалами чіткий шлях уперед. Систему вдосконалення створили гросмейстери, і вона включає понад 500 годин курсів, плани навчання, живі заходи та щоденні задачі. AI-тренер ChessMood аналізує ваші партії, знаходить сильні й слабкі сторони та будує персональний план навчання з бібліотеки курсів. Безплатний тариф Basic дає AI-аналіз партій, персональний план, перший розділ кожного курсу й понад 100 статей від гросмейстерів. Тариф Essential відкриває всю бібліотеку курсів і тренувальні інструменти за 79 USD на місяць при річній оплаті; є 7-денний пробний період і 30-денна гарантія повернення коштів.', 'ChessMood replaces jumping between random content with a clear path forward. The improvement system was crafted by grandmasters and includes 500+ hours of courses, study plans, live events and daily puzzles. The ChessMood AI coach analyzes your games, finds your strengths and weaknesses and builds a personal study plan from the course library. The free Basic plan includes AI game analysis, a custom study plan, the first section of each course and 100+ articles by grandmasters. Essential unlocks the full course library and training tools for 79 USD per month billed yearly; there is a 7-day free trial and a 30-day money-back guarantee.', 'Курси від гросмейстерів
AI-аналіз ваших партій
Персональний план навчання
Живі заходи
Щоденні задачі
Безплатний тариф Basic', 'Courses by grandmasters
AI analysis of your games
Personal study plan
Live events
Daily puzzles
Free Basic plan', 'Шахісти, які хочуть системно підвищувати рівень гри.', 'Chess players who want to improve systematically.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
