SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'get.clubee.com' OR LOWER(`name`) = LOWER('Clubee'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Clubee', NULL, 'https://get.clubee.com', NULL, NULL, 'Clubee — цифрова основа для спортивних організацій: одна платформа для федерацій, асоціацій, клубів і членів — адміністрування, змагання й турнірні таблиці, фінанси й комунікація замість розрізнених систем.', 'Clubee is the digital backbone for sports organizations: one platform for federations, associations, clubs and members — administration, competitions and standings, finance and communication instead of disconnected systems.', 'Clubee пропонує спортивним організаціям цифрову основу для трансформації. Компанія вказує на проблему: різні ролі мають різні потреби, а інфраструктура фрагментована — дані про членів, адміністрування, ігри й таблиці зберігаються в окремих системах, що заважає отримувати інсайти та залучати учасників. Платформа об''єднує національні федерації, регіональні асоціації, клуби й членів в одній системі: адміністрування, змагання, фінанси та комунікацію. Clubee працює на кількох європейських ринках і в багатьох видах спорту, допомагаючи організаціям краще використовувати свій потенціал. На сайті можна замовити демонстрацію й ознайомитися з кейсами клієнтів.', 'Clubee offers sports organizations a digital backbone for transformation. The company highlights a common problem: different roles have different needs and infrastructure is fragmented — member data, administration, games and standings sit in disconnected silos that limit insight and engagement. The platform brings national federations, regional associations, clubs and members into one system: administration, competitions, finance and communication. Clubee operates across several European markets and many sports, helping organizations unlock their potential. You can request a demo and read client case studies on the site.', 'Єдина платформа для федерацій і клубів
Адміністрування членів
Змагання й турнірні таблиці
Фінанси
Комунікація
Кілька видів спорту й ринків', 'One platform for federations and clubs
Member administration
Competitions and standings
Finance
Communication
Multiple sports and markets', 'Національні федерації, регіональні асоціації та спортивні клуби.', 'National federations, regional associations and sports clubs.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
