SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'clubspark.com' OR LOWER(`name`) = LOWER('ClubSpark'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ClubSpark', NULL, 'https://clubspark.com', NULL, NULL, 'ClubSpark — ПЗ для управління спортивним клубом і система бронювання: корти й поля, членства, оплати, змагання, коучинг, звіти, сайти та SmartAccess для клубів, тренерів, операторів і національних асоціацій.', 'ClubSpark is sports club management software and a booking system: courts and pitches, memberships, payments, competitions, coaching, reports, websites and SmartAccess for clubs, coaches, operators and national associations.', 'ClubSpark — універсальний інструмент бронювання й керування спортивним клубом, створений для клубів, тренерів, операторів об''єктів і національних асоціацій. Платформа дає гнучкі цифрові інструменти й застосунки, щоб керувати реєстраціями, членствами, доступом до ресурсів, змаганнями, тренуваннями та багато чим іншим. Можна бронювати корти й поля, приймати оплати, отримувати звіти та створювати сайти. Технологія SmartAccess дозволяє керувати доступом до об''єктів. Мета — щоб адміністративна робота займала менше часу, а на тренування й гру залишалося більше. Є окремі рішення для клубів і майданчиків, тренерів і спортивних організацій, кейси та демонстрація.', 'ClubSpark is an all-in-one sports booking and club management tool designed for clubs, coaches, operators and national associations. It provides flexible digital tools and apps to manage registrations, memberships, resource access, competitions, coaching and more. You can book courts and pitches, take payments, get reports and build websites. SmartAccess technology manages access to facilities. The goal is for admin to take less time so there is more time for coaching and playing. There are solutions for clubs and venues, coaches and sport bodies, case studies and demos.', 'Бронювання кортів і полів
Членства й оплати
Змагання й коучинг
Звіти й сайти
Контроль доступу SmartAccess', 'Court and pitch booking
Memberships and payments
