SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coachbetter.com' OR LOWER(`name`) = LOWER('Coachbetter'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Coachbetter', NULL, 'https://www.coachbetter.com', NULL, NULL, 'Coachbetter — операційна система для аматорського футболу: Club OS для керування клубом, Performance OS для єдиного стандарту тренерської роботи, застосунок тренера для планування й розвитку гравців, CityCoach і UEFA-курси.', 'Coachbetter is an operating system for grassroots football: Club OS for running the club, Performance OS for one coaching standard, a coach app for session planning and player development, CityCoach and UEFA courses.', 'Coachbetter дозволяє керувати всім футбольним клубом з однієї програми: персонал, тренери, гравці й батьки в одному місці, менше часу на розрізнені інструменти й більше — на футбол. Club OS відповідає за управління клубом, а Performance OS допомагає вибудувати єдиний стандарт тренерської роботи. Застосунок для тренера дає планування тренувань і інструменти розвитку гравців. Окремо доступна методологія тренувань Манчестер Сіті CityCoach і освітні програми з доступом до траєкторії тренерських ліцензій UEFA для окремих тренерів. Є підписки для клубів і застосунку тренера, кейси клієнтів, центр допомоги, блог і розсилка.', 'Coachbetter lets you run the entire football club from one piece of software: staff, coaches, players and parents in one place, less time on scattered tools and more time on football. Club OS handles club management, while Performance OS helps coach the club to one standard. The coach app provides session planning and player development tools. Manchester City''s CityCoach coaching methodology is also available, along with coach education offering UEFA pathway access for individual coaches. There are subscriptions for clubs and the coach app, case studies, a help center, a blog and a newsletter.', 'Club OS для керування клубом
