SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'decodechess.com' OR LOWER(`name`) = LOWER('DecodeChess'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'DecodeChess', NULL, 'https://decodechess.com', NULL, NULL, 'DecodeChess — шаховий AI-репетитор, що пояснює ходи шахового рушія зрозумілою людською мовою: розбір партій і позицій, глибокі пояснення, гра проти комп''ютера; безплатно 1 партія на день, безліміт — від 8,25 USD.', 'DecodeChess is an AI chess tutor that explains a chess engine''s moves in human language: game and position analysis, deep explanations and play vs computer; 1 free game per day, unlimited from 8.25 USD.', 'DecodeChess вирішує проблему, знайому кожному, хто аналізував партії з рушієм: комп''ютер показує оптимальний хід, але не пояснює чому. Цей AI-репетитор пояснює логіку ходів багатою й інтуїтивною мовою, допомагаючи зрозуміти ідеї, плани й приховані можливості позиції. Можна розбирати власні партії та окремі позиції, отримувати глибокі пояснення й грати проти комп''ютера. Сервіс рекомендують провідні гросмейстери й тренери, зокрема Аніш Гірі та Борис Гельфанд. Безплатний тариф дає розбір однієї партії на день, а безлімітна підписка з глибокими поясненнями та підвищеною обчислювальною потужністю коштує 8,25 USD на місяць або 84 USD на рік; діє 7-денна гарантія повернення.', 'DecodeChess solves a problem familiar to anyone who has analyzed games with an engine: the computer shows the best move but not why. This AI tutor explains the reasoning in rich, intuitive language, helping you understand ideas, plans and hidden possibilities in a position. You can decode your own games and individual positions, get deep explanations and play against the computer. Top grandmasters and coaches, including Anish Giri and Boris Gelfand, recommend it. The free plan decodes one game per day, while the unlimited subscription with deep explanations and extra computing power costs 8.25 USD per month or 84 USD per year, with a 7-day money-back guarantee.', 'Пояснення ходів людською мовою
Розбір партій і позицій
Глибокі пояснення
Гра проти комп''ютера
Безплатна партія щодня', 'Move explanations in human language
Game and position analysis
Deep explanations
Play vs computer
One free game a day', 'Шахісти будь-якого рівня й тренери, які хочуть розуміти ідеї рушія.', 'Chess players of any level and coaches who want to understand engine ideas.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
