SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'easy2coach.net' OR LOWER(`name`) = LOWER('easy2coach'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'easy2coach', NULL, 'https://www.easy2coach.net', NULL, NULL, 'easy2coach — німецька платформа для футбольних тренерів: Team Manager для організації команди, понад 3000 вправ для планування тренувань і тактична дошка; безплатний тариф без обмеження в часі, iOS, Android і веб.', 'easy2coach is a German platform for football coaches: Team Manager for team organization, 3,000+ drills for session planning and a tactics board; a free plan with no time limit, on iOS, Android and web.', 'easy2coach працює на ринку вже 20 років і поєднує організацію команди, планування тренувань і тактичну дошку для тренерів, які хочуть більше часу приділяти коучингу. Team Manager бере на себе організацію, комунікацію й планування: склад, батьки, календар, підтвердження й відмови, командний чат і командна каса з внесками. Розділ Training пропонує понад 3000 футбольних вправ для планування занять, а Tactics — тактичну дошку з багатьма видами. Безплатний тариф без обмеження в часі й без картки включає керування командою, комунікацію, календар, касу, тактичну дошку та базові тренування (5 вправ на день); платні плани розширюють доступ. Застосунок працює на iOS, Android і у вебі.', 'easy2coach has been on the market for 20 years and combines team organization, training planning and a tactics board for coaches who want to spend more time coaching. Team Manager handles organization, communication and planning: roster, parents, calendar, attendance confirmations, team chat and a team cash box with fees. The Training section offers 3,000+ football drills for planning sessions, and Tactics provides a tactics board with many views. The free plan has no time limit and no card and includes team management, communication, calendar, team cash, the tactics board and training basics (5 drills per day); paid plans expand access. The app runs on iOS, Android and the web.', 'Team Manager: склад, календар, чат
