SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fastmodelsports.com' OR LOWER(`name`) = LOWER('FastModel Sports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FastModel Sports', NULL, 'https://fastmodelsports.com', NULL, NULL, 'FastModel Sports (тепер частина Hudl) — набір програм для тренерів: FastDraw для малювання й організації комбінацій та плейбуків, FastScout для скаутингу суперників і FastRecruit для рекрутингу; баскетбол, хокей та інші.', 'FastModel Sports (now part of Hudl) is a coaching software suite: FastDraw for diagramming and organizing plays and playbooks, FastScout for opponent scouting and FastRecruit for recruiting; basketball, hockey and more.', 'FastModel Sports створює програмне забезпечення, що допомагає тренерам залишатися конкурентними. FastDraw дозволяє швидко малювати, впорядковувати й поширювати ігрові комбінації та вправи, створюючи цифрові плейбуки. FastScout допомагає готувати звіти про суперників, а FastRecruit — вести рекрутинг гравців. Рішення адаптовані для баскетболу на всіх рівнях — від дитячого й шкільного до коледжів, міжнародних і професійних команд, — а також для хокею, американського футболу, футболу й волейболу. Є бібліотека Playbank з готовими комбінаціями, блог і портал адміністратора. FastModel тепер входить до складу Hudl.', 'FastModel Sports builds software that keeps coaches competitive. FastDraw lets you quickly diagram, organize and share plays and drills, creating digital playbooks. FastScout helps prepare opponent scouting reports, and FastRecruit supports player recruiting. Solutions cover basketball at every level — youth, high school, college, international and professional — as well as hockey, football, soccer and volleyball. There is the Playbank library of ready-made plays, a blog and an admin portal. FastModel is now part of Hudl.', 'FastDraw — малювання комбінацій
Цифрові плейбуки
FastScout — скаутинг суперників
FastRecruit — рекрутинг
Бібліотека Playbank', 'FastDraw play diagramming
Digital playbooks
FastScout opponent scouting
FastRecruit recruiting
Playbank library', 'Тренери з баскетболу, хокею, футболу та волейболу різних рівнів.', 'Basketball, hockey, football and volleyball coaches at all levels.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
