SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fifatrainingcentre.com' OR LOWER(`name`) = LOWER('FIFA Training Centre'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FIFA Training Centre', NULL, 'https://www.fifatrainingcentre.com', NULL, NULL, 'FIFA Training Centre — безплатна онлайн-академія FIFA для тренерів: принципи гри, спостереження за турнірами, бібліотека ігор, вправи для еліти, розвитку талантів, дитячого футболу, пляжного футболу й футзалу, розвиток тренерів.', 'FIFA Training Centre is FIFA''s free online academy for coaches: game principles, tournament observations, a game library, practices for elite, talent development, grassroots, beach soccer and futsal, and coach development.', 'FIFA Training Centre відкриває безплатний доступ до експертизи FIFA для тренерів будь-де у світі. Розділ «Гра» містить принципи гри, спостереження за турнірами, зокрема чемпіонатом світу, бібліотеку ігор і футбольну термінологію. Розділ «Практика» пропонує тренувальні матеріали для елітного рівня, розвитку талантів, масового й дитячого футболу, пляжного футболу та футзалу. Окремо розглянуто середовище розвитку, інтерв''ю з експертами та розвиток тренерів: технічне лідерство, високі досягнення й підготовку воротарів. Після створення облікового запису FIFA відкривається спільнота з налаштуваннями контенту під ваші інтереси.', 'FIFA Training Centre gives coaches anywhere in the world free access to FIFA expertise. The Game section covers game principles, tournament observations, including the World Cup, a game library and football language. The Practice section offers training material for the elite level, talent development, grassroots and youth, beach soccer and futsal. Further sections cover the environment, expert interviews and coaching development: technical leadership, high performance and goalkeeping. Creating a FIFA account opens a community area with content preferences tailored to your interests.', 'Принципи гри й аналіз турнірів
Тренувальні вправи для різних рівнів
Дитячий, пляжний футбол і футзал
Підготовка воротарів
Розвиток тренерів
Безплатно', 'Game principles and tournament analysis
Practices for different levels
Youth, beach soccer and futsal
Goalkeeping
Coach development
Free', 'Футбольні тренери всіх рівнів, технічні директори й викладачі.', 'Football coaches at all levels, technical directors and educators.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
