SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'glofox.com' OR LOWER(`name`) = LOWER('Glofox'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Glofox', NULL, 'https://www.glofox.com', NULL, NULL, 'Glofox — універсальне ПЗ для фітнес-бізнесу: управління членствами, розклад і бронювання, оплати, брендований застосунок, CRM, контроль доступу, звітність для мереж і AI-агенти, що відповідають на дзвінки й чати.', 'Glofox is all-in-one fitness business software: membership management, scheduling and booking, payments, a branded app, CRM, access control, multi-location reporting and AI agents that answer calls and chats.', 'Glofox допомагає фітнес-операторам утримувати учасників і збільшувати дохід. Платформа поєднує розклад, оплати й адміністрування в одному місці, допомагає заповнювати класи, конвертувати ліди та залучати нових учасників. Для взаємодії з клієнтами є брендований застосунок, повідомлення та інструменти спільноти, а для масштабування — керування кількома локаціями, звітність і аналітика. Серед функцій — управління членствами, CRM, білінг, контроль доступу й чек-ін, керування персоналом. AI-агенти ABC відповідають на кожен дзвінок і чат миттєво. Рішення підходить для залів, студій пілатесу, йоги, сайклу, боксу, персонального тренінгу й бойових мистецтв.', 'Glofox helps fitness operators increase member retention and grow revenue. The platform brings scheduling, payments and admin into one place, helps fill classes, convert leads and win new members. For engagement there is a custom branded app, messaging and community tools, and for scaling there are multi-location controls, reporting and insights. Features include membership management, CRM, billing, access control and check-in, and staff management. ABC AI agents answer every call and chat instantly. It suits gyms and Pilates, yoga, cycling, boxing, PT and martial arts studios.', 'Управління членствами й білінг
Розклад і бронювання
Брендований застосунок
CRM і маркетинг
Контроль доступу
AI-агенти для дзвінків і чатів', 'Membership management and billing
Scheduling and booking
Custom branded app
CRM and marketing
Access control
AI agents for calls and chats', 'Фітнес-зали, студії та мережі клубів.', 'Fitness gyms, studios and club chains.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
