SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gymcatch.com' OR LOWER(`name`) = LOWER('Gymcatch'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gymcatch', NULL, 'https://gymcatch.com', NULL, NULL, 'Gymcatch — ПЗ для фітнес-бізнесу з бронюванням очних, живих онлайн і записаних занять: розклад, оплати, членства, віртуальні сесії, комунікація й аналітика для інструкторів, студій і тренерів; місяць безплатно.', 'Gymcatch is fitness business software with booking for in-person, live virtual and on-demand sessions: scheduling, payments, memberships, virtual classes, communication and insights for instructors, studios and trainers; one month free.', 'Gymcatch — доступне й просте рішення для керування та розвитку фітнес-бізнесу, а для клієнтів — зручний спосіб бронювати заняття. Можна пропонувати очні тренування, живі онлайн-сесії та записані заняття на вимогу. Функції включають бронювання й розклад, прийом оплат, інструменти, що економлять час, управління членствами, проведення віртуальних сесій, комунікацію й спільноту, а також бізнес-аналітику з підтримкою. Рішення розраховане на інструкторів танців і групового фітнесу, зали й студії, персональних тренерів, інструкторів пілатесу, пол-денсу й повітряної акробатики, йоги, велнес-фахівців, бойові мистецтва та спортивні тренування. Перший місяць безплатний без картки.', 'Gymcatch is an affordable, easy solution for managing and growing a fitness business, and a convenient way for clients to book. You can offer in-person training, live virtual sessions and on-demand classes. Features include booking and scheduling, taking payments, time-saving tools, membership management, virtual session delivery, communication and community, and business insight with support. It is built for dance and group fitness instructors, gyms and studios, personal trainers, Pilates, pole and aerial, and yoga instructors, wellness practitioners, martial arts and sports training. The first month is free with no card required.', 'Бронювання очних і онлайн-занять
Записані заняття на вимогу
Оплати й членства
Комунікація зі спільнотою
Бізнес-аналітика
Місяць безплатно', 'Booking for in-person and online sessions
On-demand classes
Payments and memberships
Community communication
Business insights
One month free', 'Інструктори, персональні тренери, студії та невеликі зали.', 'Instructors, personal trainers, studios and small gyms.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
