SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gymdesk.com' OR LOWER(`name`) = LOWER('Gymdesk'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gymdesk', NULL, 'https://gymdesk.com', NULL, NULL, 'Gymdesk — ПЗ для залів, що працює у фоні: автоматичний білінг, відвідуваність, членства, бронювання, каса, доступ до закладу, email/SMS-маркетинг, робота з лідами, звіти й прогноз доходу; 30 днів безплатно.', 'Gymdesk is gym software that runs in the background: automated billing, attendance, memberships, booking, POS, facility access, email/SMS marketing, lead management, reporting and revenue forecasting; 30 days free.', 'Gymdesk бере на себе рутинні задачі, щоб власник залу перестав ганятися за невдалими платежами й повернув собі вечори. Блок «менше адміністрування» включає членства, бронювання, білінг, касу, доступ до закладу, мобільний застосунок, вибір платіжних систем і облік відвідуваності. Блок «більше учасників» — email- і SMS-маркетинг, автоматизації, керування лідами, реферали, відгуки, лендинги та сайт. Блок аналітики — звіти, аналітика відвідуваності, дашборд, прогноз доходу та інсайти щодо учасників. Вбудовані платежі Gymdesk Payments спрощують обробку оплат. Рішення підходить для шкіл бойових мистецтв, фітнес-залів, кросфіту, студій пілатесу та йоги, гімнастики й танців; 30 днів безплатно.', 'Gymdesk takes care of routine work so gym owners can stop chasing failed payments and get their evenings back. The less-admin block covers memberships, booking, billing, point of sale, facility access, a mobile app, payment processor choice and attendance. The more-members block includes email and SMS marketing, automations, lead management, referrals, reviews, landing pages and a website. The analytics block offers reporting, attendance analytics, a dashboard, revenue forecasting and member insights. Built-in Gymdesk Payments simplifies payment processing. It suits martial arts schools, fitness gyms, CrossFit, Pilates and yoga studios, gymnastics and dance; 30 days free.', 'Автоматичний білінг і членства
Бронювання й облік відвідуваності
Email/SMS-маркетинг і ліди
Звіти й прогноз доходу
Вбудовані платежі
30 днів безплатно', 'Automated billing and memberships
Booking and attendance
Email/SMS marketing and leads
Reporting and revenue forecasting
Built-in payments
30 days free', 'Школи бойових мистецтв, фітнес-зали, студії йоги й пілатесу.', 'Martial arts schools, fitness gyms, yoga and Pilates studios.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
