SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gymmaster.com' OR LOWER(`name`) = LOWER('GymMaster'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GymMaster', NULL, 'https://www.gymmaster.com', NULL, NULL, 'GymMaster — універсальне ПЗ для залів із вбудованим доступом 24/7 через Bluetooth без сторонніх систем: автоматичний білінг і стягнення боргів, застосунок для учасників, каса, онлайн-бронювання й запис, маркетинг.', 'GymMaster is all-in-one gym software with built-in 24/7 Bluetooth door access and no third parties: auto-billing and debt collection, a member app, POS, online booking and sign-ups, and marketing.', 'GymMaster позиціонується як ПЗ, що переводить адміністрування залу на автопілот за невелику ціну. Його особливість — вбудований контроль доступу 24/7 через Bluetooth-замки без сторонніх рішень, що дозволяє відкривати зал довше й економити час і гроші. Платформа включає інтегрований білінг з автоматичними списаннями та стягненням боргів, гнучкі членства, онлайн-бронювання й онлайн-реєстрацію нових учасників, касу, застосунок для учасників, автоматизацію та маркетинг. Компанія обіцяє швидке налаштування й результат за лічені години, а також акцентує увагу на клієнтській підтримці. На сайті можна замовити безплатну демонстрацію та переглянути тарифи.', 'GymMaster positions itself as software that puts gym admin on autopilot at a fraction of the cost. Its distinguishing feature is built-in 24/7 Bluetooth door access with no third-party systems, letting gyms open longer while saving time and money. The platform includes integrated billing with auto-debits and debt collection, customizable memberships, online booking and online sign-ups, a point of sale, a member app, automation and marketing. The company promises quick setup with results within hours and emphasizes customer support. You can request a free demo and see pricing on the site.', 'Доступ 24/7 через Bluetooth
Автоматичний білінг і стягнення боргів
Гнучкі членства
Онлайн-бронювання й реєстрація
Застосунок для учасників
Каса й маркетинг', '24/7 Bluetooth access
Auto-billing and debt collection
Customizable memberships
Online booking and sign-ups
Member app
POS and marketing', 'Власники тренажерних залів, зокрема з цілодобовим доступом.', 'Gym owners, including 24/7 access gyms.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
