SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hapana.com' OR LOWER(`name`) = LOWER('Hapana'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hapana', NULL, 'https://www.hapana.com', NULL, NULL, 'Hapana — наскрізне ПЗ для залів і фітнес-студій: управління учасниками, маркетингова автоматизація, брендований застосунок, дашборди, мережі й франшизи та застосунок челенджів для мотивації спільноти.', 'Hapana is end-to-end software for gyms and fitness studios: member management, marketing automation, a branded app, reporting dashboards, multisite and franchise support and a challenge app to motivate the community.', 'Hapana — комплексне рішення для амбітних фітнес-бізнесів, що прагнуть залученості й зростання. Модуль управління учасниками допомагає відстежувати клієнтів і спрощує операційну роботу, маркетингова автоматизація — стежити за лідами й продажами, а брендований застосунок — тримати учасників на зв''язку. Дашборди звітності дають змогу ухвалювати рішення на основі даних, а підтримка мереж і франшиз дозволяє розширюватися. Окремий застосунок челенджів мотивує й винагороджує спільноту. Hapana розраховано на студії пілатесу й реформера, HIIT і функціонального тренінгу, сайклу, MMA та боксу, зали, йогу, барре, а також на велнес-центри й центри відновлення.', 'Hapana is a complete solution for ambitious fitness businesses seeking engagement and growth. Member management keeps track of clients and simplifies operations, marketing automation keeps you on top of leads and sales, and a branded app keeps members connected. Reporting dashboards support data-driven decisions, and multisite and franchise support lets you expand. A separate challenge app motivates and rewards the community. Hapana serves Pilates and reformer, HIIT and functional, indoor cycling, MMA and boxing studios, gyms, yoga and barre, as well as wellness and recovery centers.', 'Управління учасниками
Маркетингова автоматизація
Брендований застосунок
Дашборди звітності
Мережі й франшизи
Застосунок челенджів', 'Member management
Marketing automation
Branded app
Reporting dashboards
Multisite and franchises
Challenge app', 'Фітнес-студії, зали, мережі й франшизи.', 'Fitness studios, gyms, chains and franchises.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
