SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'insights.gg' OR LOWER(`name`) = LOWER('Insights Capture'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Insights Capture', NULL, 'https://insights.gg', NULL, NULL, 'Insights Capture — безплатна програма для запису ігор і кліпів на ПК: автоматично записує кожен матч у 10 000+ іграх без втрати кадрів, зберігає кліпи за два кліки, має інструмент розбору VOD для тренерів і команд.', 'Insights Capture is free game recording and clipping software for PC: it auto-records every match in 10,000+ games with no frame loss, saves clips in two clicks and includes a VOD review tool for coaches and teams.', 'Insights Capture — десктопний застосунок для Windows, який автоматично записує кожен матч у понад 10 000 іграх, тож ви не пропустите жодного моменту. Кліпи зберігаються за два кліки без втрати кадрів. Для покращення гри є інструмент розбору VOD: тренери й команди можуть переглядати записи, коментувати та аналізувати матчі у Valorant, League of Legends, Counter-Strike 2, Apex Legends, Rainbow 6 Siege, Fortnite та інших іграх. Базова версія безплатна й має 5 ГБ сховища. Платні плани для тренерів і команд додають місця для Elite-користувачів, більше сховища, роботу без реклами, постійне завантаження на сервери та розширені налаштування; командні пакети дають знижку.', 'Insights Capture is a Windows desktop app that automatically records every match in 10,000+ games so you never miss a moment. Clips are saved in two clicks with no frame loss. To improve your play there is a VOD review tool: coaches and teams can review recordings, comment and analyze matches in Valorant, League of Legends, Counter-Strike 2, Apex Legends, Rainbow 6 Siege, Fortnite and more. The basic version is free with 5 GB of storage. Paid plans for coaches and teams add Elite seats, more storage, no ads, permanent uploads to servers and advanced customization; team bundles are discounted.', 'Автозапис матчів у 10 000+ іграх
