-- iTero — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'itero.gg' OR LOWER(`name`) = LOWER('iTero'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'iTero', NULL, 'https://www.itero.gg', NULL, NULL, 'iTero — застосунок-компаньйон і тренер для League of Legends: персональні піки, збірки й макростратегії під ваш стиль гри, симулятор драфту, конструктор пулу чемпіонів, квіз і ARAM; повністю відповідає правилам Riot.', 'iTero is a League of Legends companion app and coach: personalized picks, builds and macro strategies for your playstyle, a drafting simulator, champion pool builder, quiz and ARAM; fully Riot compliant.', 'iTero — сторонній застосунок-компаньйон для League of Legends, що дає змагальним гравцям практичні поради, щоб краще драфтити, збирати предмети й переграти суперника в кожній грі. Застосунок вчиться на ваших помилках і розвивається разом із вашими перемогами: спираючись на велику базу даних, він пропонує піки, збірки та макростратегії, повністю персоналізовані під ваш стиль гри. Серед інструментів — симулятор драфту, конструктор пулу чемпіонів, квіз, сторінки чемпіонів, розділ ARAM і статті. Розробники наголошують, що застосунок повністю відповідає правилам Riot Games. Інтерфейс доступний кількома мовами, а сам застосунок можна завантажити безплатно.', 'iTero is a third-party League of Legends companion app that gives competitive players actionable insights to outdraft, outbuild and outplay opponents every game. The app learns from your mistakes and evolves with your victories: drawing on a large database, it suggests picks, builds and macro strategies fully personalized to your playstyle. Tools include a drafting simulator, a champion pool builder, a quiz, champion pages, an ARAM section and articles. The developers stress that the app is fully compliant with Riot Games rules. The interface is available in several languages, and the app is free to download.', 'Персональні піки й збірки
Макростратегії під ваш стиль
Симулятор драфту
Конструктор пулу чемпіонів
Режим ARAM
Відповідність правилам Riot', 'Personalized picks and builds
Macro strategies for your style
Drafting simulator
Champion pool builder
ARAM mode
Riot compliant', 'Гравці в League of Legends, які хочуть грати змагально й прогресувати.', 'League of Legends players who want to compete and improve.', 'desktop,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
