-- Jersey Watch — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'jerseywatch.com' OR LOWER(`name`) = LOWER('Jersey Watch'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Jersey Watch', NULL, 'https://www.jerseywatch.com', NULL, NULL, 'Jersey Watch — універсальна платформа для молодіжних і місцевих спортивних організацій: конструктор сайтів, онлайн-реєстрація гравців, оплати, повідомлення родинам і розклади; перший місяць — 19 USD. Без картки.', 'Jersey Watch is an all-in-one platform for youth and community sports organizations: website builder, online player registration, payments, messaging to families and scheduling; the first month is 19 USD.', 'Jersey Watch допомагає молодіжним і місцевим спортивним організаціям створити сайт, реєструвати гравців, приймати оплати й тримати родини в курсі в одному місці. Платформа включає конструктор сайтів, онлайн-реєстрацію, керування платежами, розсилку повідомлень і розклади. Почати можна безплатно й без картки — платити потрібно лише тоді, коли ви готові запустити сайт. Перший місяць після запуску коштує 19 USD, і за цей час команда з повним сервісом налаштує сайт і реєстрацію з індивідуальним дизайном, перенесе контент зі старого сайту та підключить безплатний або власний домен. Далі підписка коштує 348 USD на рік, скасувати можна будь-коли.', 'Jersey Watch helps youth and community sports organizations build a website, register players, manage payments and keep families informed in one place. The platform includes a website builder, online registration, payment management, messaging and scheduling. You can start for free with no credit card and only pay when you are ready to go live. The first month after launch costs 19 USD, during which the full-service team sets up your website and registration with a custom design, migrates content from your old site and connects a free or your own domain. After that the subscription is 348 USD per year, and you can cancel anytime.', 'Конструктор сайтів
Онлайн-реєстрація гравців
Керування оплатами
Повідомлення родинам
Розклади
Налаштування й перенесення сайту командою', 'Website builder
Online player registration
Payment management
Messaging to families
Scheduling
Site setup and migration by the team', 'Молодіжні ліги, клуби й місцеві спортивні організації.', 'Youth leagues, clubs and community sports organizations.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
