SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kovaaks.com' OR LOWER(`name`) = LOWER('KovaaK''s'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'KovaaK''s', NULL, 'https://www.kovaaks.com', NULL, NULL, 'KovaaK''s Aim Trainer — тренажер прицілювання для FPS-гравців: понад 175 000 сценаріїв від спільноти, плейлисти, трекер бенчмарків, змагання, редактор карт, гнучкі налаштування та копіювання фізики ігор.', 'KovaaK''s Aim Trainer is an aim trainer for FPS players: 175,000+ community scenarios, playlists, a benchmark tracker, competitions, a map editor, deep customization and cloned game physics.', 'KovaaK''s — популярний тренажер прицілювання, яким користуються професійні гравці, стримери та звичайні гравці. Він дозволяє тренувати навички стрільби в шутерах на понад 175 000 сценаріях, створених спільнотою, і ділитися плейлистами з іншими. Вбудований редактор карт, безмежні налаштування та відтворення фізики конкретних ігор допомагають тренуватися в умовах, максимально наближених до реальної гри. На сайті можна переглядати трендові сценарії й плейлисти, таблиці результатів, трекер бенчмарків для оцінки рівня, глобальні змагання, а також користуватися конвертером чутливості та конструктором прицілу. Після входу доступна персональна стрічка активності й підписки на гравців.', 'KovaaK''s is a popular aim trainer used by pros, streamers and everyday players. It lets you train shooter aiming skills on 175,000+ player-created scenarios and share playlists with others. A built-in map editor, infinite customization and cloned game physics help you train in conditions close to real games. On the site you can browse trending scenarios and playlists, leaderboards, a benchmark tracker to assess your level and global competitions, and use the sensitivity converter and crosshair creator. Logged-in users get a personalized activity feed and can follow players.', '175 000+ сценаріїв від спільноти
