-- Lichess — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lichess.org' OR LOWER(`name`) = LOWER('Lichess'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Lichess', NULL, 'https://lichess.org', NULL, NULL, 'Lichess — повністю безплатний відкритий шаховий сервер без реклами: гра з комп''ютером, друзями й суперниками, турніри, задачі, навчання основам, дошка аналізу з рушієм, дебютна база, трансляції й каталог тренерів.', 'Lichess is a completely free, open-source, ad-free chess server: play the computer, friends or opponents, tournaments, puzzles, chess basics, an engine analysis board, an opening explorer, broadcasts and a coach directory.', 'Lichess — безплатний, вільний і відкритий шаховий сервер без реклами, реєстрації для гри та плагінів. Можна грати з комп''ютером, друзями чи випадковими суперниками, брати участь в арена- й швейцарських турнірах, сеансах одночасної гри. Для тренування є задачі з тематиками, панель прогресу, режими Puzzle Streak, Storm і Racer. Розділ навчання містить основи шахів, практику, тренування координат, інтерактивні студії та каталог тренерів. Інструменти включають дошку аналізу з рушієм, дебютну базу, редактор позицій, імпорт партій і розширений пошук. Також є трансляції турнірів, Lichess TV, відеобібліотека, команди, форум і блог. Проєкт існує на пожертви.', 'Lichess is a free, libre, open-source chess server with no ads, no registration needed to play and no plugins. You can play the computer, friends or random opponents, join arena and Swiss tournaments and simultaneous exhibitions. For training there are themed puzzles, a puzzle dashboard and the Puzzle Streak, Storm and Racer modes. The learning section covers chess basics, practice, coordinate training, interactive studies and a coach directory. Tools include an engine analysis board, an opening explorer, a board editor, game import and advanced search. There are also tournament broadcasts, Lichess TV, a video library, teams, a forum and a blog. The project is funded by donations.', 'Безплатна гра без реклами
Турніри й сеанси
Задачі й тренувальні режими
Дошка аналізу з рушієм
Навчання й студії
Каталог тренерів', 'Free ad-free play
Tournaments and simuls
Puzzles and training modes
Engine analysis board
Learning and studies
Coach directory', 'Шахісти будь-якого рівня, тренери й шкільні гуртки.', 'Chess players of any level, coaches and school clubs.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
