INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'sports' AND s.`name` = 'Масовий фітнес і тренування' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Lichess is a completely free, open-source, ad-free chess server: play the computer, friends or opponents, tournaments, puzzles, chess basics, an engine analysis board, an opening explorer, broadcasts and a coach directory.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Lichess is a free, libre, open-source chess server with no ads, no registration needed to play and no plugins. You can play the computer, friends or random opponents, join arena and Swiss tournaments and simultaneous exhibitions. For training there are themed puzzles, a puzzle dashboard and the Puzzle Streak, Storm and Racer modes. The learning section covers chess basics, practice, coordinate training, interactive studies and a coach directory. Tools include an engine analysis board, an opening explorer, a board editor, game import and advanced search. There are also tournament broadcasts, Lichess TV, a video library, teams, a forum and a blog. The project is funded by donations.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Free ad-free play
Tournaments and simuls
Puzzles and training modes
Engine analysis board
Learning and studies
Coach directory', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Chess players of any level, coaches and school clubs.', 'manual' FROM DUAL WHERE @new = 1;
