-- Metafy — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'metafy.gg' OR LOWER(`name`) = LOWER('Metafy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Metafy', NULL, 'https://metafy.gg', NULL, NULL, 'Metafy — платформа для гравців, які серйозно ставляться до ігор: окремий хаб для кожної гри з гайдами, коучингом від креаторів і тренерів, подіями та Discord-спільнотами, з відгуками на гайди й навчання.', 'Metafy is a platform for players who take their game seriously: a hub for every game with guides, coaching from creators and coaches, events and Discord communities, plus reviews of guides and training.', 'Metafy — це місце для тих, хто серйозно ставиться до своєї гри й хоче вчитися в провідних креаторів і тренерів. Кожна гра має власний хаб на Metafy: там креатори публікують свої матеріали, а гравці знаходять потрібне. У хабах доступні гайди, індивідуальний коучинг, події та Discord-спільноти. Можна шукати гру й переглядати, що є всередині, а також читати свіжі відгуки на гайди, щоб обрати якісне навчання. Для креаторів і тренерів платформа стає способом монетизувати свої знання. Metafy працює в браузері, і для коректної роботи відео й оплати потрібна сучасна версія браузера. Платформа охоплює десятки популярних ігор і постійно додає нові хаби.', 'Metafy is a place for players who take their game seriously and want to learn from the best creators and coaches. Every game has its own hub on Metafy: creators publish their content there and players find what they need. Hubs offer guides, one-on-one coaching, events and Discord communities. You can search for a game, explore what is inside and read recent reviews of guides to choose quality training. For creators and coaches, the platform is a way to monetize their knowledge. Metafy runs in the browser and needs an up-to-date browser for video and checkout to work properly. The platform covers dozens of popular games and keeps adding new hubs.', 'Хаби для кожної гри
Гайди від креаторів
Індивідуальний коучинг
Події та Discord-спільноти
Відгуки на матеріали', 'Hubs for every game
Guides from creators
One-on-one coaching
Events and Discord communities
Reviews of content', 'Гравці й кіберспортсмени, які хочуть покращити навички, а також ігрові тренери.', 'Gamers and esports players who want to improve, and gaming coaches.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
