INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Metafy is a platform for players who take their game seriously: a hub for every game with guides, coaching from creators and coaches, events and Discord communities, plus reviews of guides and training.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Metafy is a place for players who take their game seriously and want to learn from the best creators and coaches. Every game has its own hub on Metafy: creators publish their content there and players find what they need. Hubs offer guides, one-on-one coaching, events and Discord communities. You can search for a game, explore what is inside and read recent reviews of guides to choose quality training. For creators and coaches, the platform is a way to monetize their knowledge. Metafy runs in the browser and needs an up-to-date browser for video and checkout to work properly. The platform covers dozens of popular games and keeps adding new hubs.', 'manual' FROM DUAL WHERE @new = 1;
