-- Mindbody — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mindbodyonline.com' OR LOWER(`name`) = LOWER('Mindbody'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mindbody', NULL, 'https://www.mindbodyonline.com', NULL, NULL, 'Mindbody — програмне забезпечення для фітнес- і велнес-бізнесу: розклад, оплати, персонал, звітність, маркетингові кампанії, брендовані віджети для сайту, ClassPass для бізнесу та застосунок для клієнтів, де вас знайдуть.', 'Mindbody is software for fitness and wellness businesses: scheduling, payments, staff, reporting, marketing campaigns, branded website widgets, ClassPass for business and a consumer app where clients discover you.', 'Mindbody допомагає студіям, залам і велнес-закладам вести щоденну роботу та розвиватися. Для операційної діяльності є бізнес-застосунок, з якого можна керувати справами будь-де, модуль оплат для відстеження й захисту транзакцій, керування персоналом, оптимізація розкладу та звіти про ефективність. Для зростання — застосунок Mindbody, де заклад знаходять активні користувачі, маркетингові інструменти для кампаній, ClassPass для бізнесу, щоб заповнювати вільні місця, і фінансування Mindbody Capital. Брендовані веб-інструменти дозволяють додати бронювання на власний сайт. Клієнти можуть бронювати заняття й процедури через застосунок Mindbody. Демо й підтримка доступні на сайті.', 'Mindbody helps studios, gyms and wellness businesses run day to day and grow. For operations there is a business app to run things from anywhere, a payments module to manage, track and secure transactions, staff management, calendar optimization and performance reporting. For growth there is the Mindbody consumer app where active users discover businesses, marketing tools for campaigns, ClassPass for business to fill open spots and Mindbody Capital financing. Branded web tools let you add booking to your own site. Clients can book classes and appointments in the Mindbody app. Demos and support are available on the site.', 'Розклад і бронювання
Оплати й звітність
Керування персоналом
Маркетингові кампанії
ClassPass для бізнесу
Віджети бронювання для сайту', 'Scheduling and booking
Payments and reporting
Staff management
Marketing campaigns
ClassPass for business
Booking widgets for your site', 'Фітнес-студії, зали, йога-студії, спа та велнес-заклади.', 'Fitness studios, gyms, yoga studios, spas and wellness businesses.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
