INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Mindbody helps studios, gyms and wellness businesses run day to day and grow. For operations there is a business app to run things from anywhere, a payments module to manage, track and secure transactions, staff management, calendar optimization and performance reporting. For growth there is the Mindbody consumer app where active users discover businesses, marketing tools for campaigns, ClassPass for business to fill open spots and Mindbody Capital financing. Branded web tools let you add booking to your own site. Clients can book classes and appointments in the Mindbody app. Demos and support are available on the site.', 'manual' FROM DUAL WHERE @new = 1;
