-- Mobalytics — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mobalytics.gg' OR LOWER(`name`) = LOWER('Mobalytics'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mobalytics', NULL, 'https://mobalytics.gg', NULL, NULL, 'Mobalytics — ігровий помічник для LoL, TFT, Path of Exile 2, Diablo 4, Deadlock та інших: експертні рекомендації меті під ваш рівень і стиль, аналіз ігор для пошуку слабких місць і десктопний застосунок для Windows.', 'Mobalytics is a gaming companion for LoL, TFT, Path of Exile 2, Diablo 4, Deadlock and more: expert meta recommendations for your skill and playstyle, game analysis to find weaknesses and a Windows desktop app.', 'Mobalytics — універсальний компаньйон, що допомагає легше опановувати улюблені ігри. Він підтримує League of Legends, Teamfight Tactics, Path of Exile 2, Diablo 4, Borderlands 4, Nightreign, Deadlock, Monster Hunter Wilds та інші. Сервіс тримає вас в курсі меті кожного патча завдяки експертним рекомендаціям, персоналізованим під ваш рівень гри та стиль. Аналіз ваших ігор допомагає визначити, які навички потребують покращення найбільше, і виправити слабкі сторони, щоб частіше перемагати й швидше підніматися в ранзі. Mobalytics доступний у браузері та як десктопний застосунок для Windows, який працює поруч із грою.', 'Mobalytics is an all-in-one companion that makes mastering your favorite games easier. It supports League of Legends, Teamfight Tactics, Path of Exile 2, Diablo 4, Borderlands 4, Nightreign, Deadlock, Monster Hunter Wilds and more. It keeps you on top of the meta every patch with expert recommendations personalized for your skill level and playstyle. Analysis of your games pinpoints the areas that need the most improvement so you can fix weaknesses, win more and climb faster. Mobalytics is available in the browser and as a Windows desktop app that runs alongside your game.', 'Підтримка LoL, TFT, PoE2, Diablo 4 та інших
Рекомендації меті під ваш рівень
Аналіз ігор і слабких місць
Десктопний застосунок для Windows
Оновлення під кожен патч', 'Support for LoL, TFT, PoE2, Diablo 4 and more
Meta recommendations for your level
Game analysis and weaknesses
Windows desktop app
Updates every patch', 'Гравці в LoL, TFT, ARPG та інші ігри, які хочуть грати краще.', 'LoL, TFT, ARPG and other players who want to play better.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
