-- MOJO — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mojo.sport' OR LOWER(`name`) = LOWER('MOJO'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MOJO', NULL, 'https://mojo.sport', NULL, NULL, 'MOJO — застосунок для родин і тренерів дитячих команд, тепер у складі TeamSnap: сотні відео й планів тренувань, які подобаються дітям, розклад, облік відвідуваності, повідомлення, рахунок ігор, трансляції й хайлайти.', 'MOJO is an app for families and youth team coaches, now part of TeamSnap: hundreds of kid-friendly practice videos and plans, scheduling, attendance, messaging, game scoring, live streaming and highlights.', 'MOJO — універсальне рішення для родин, чиї діти займаються спортом, і для тренерів-волонтерів. Розділ коучингу пропонує ефективні тренування, які подобаються дітям: сотні відео й планів занять від провідних фахівців у спорті. Керування командою спрощує розклад, облік відвідуваності, повідомлення та інші організаційні задачі. У зоні FanZone можна вести рахунок гри, транслювати матчі наживо й зберігати хайлайти, додаючи все до профілю гравця, щоб ділитися з рідними на будь-якому пристрої. MOJO тепер є частиною TeamSnap. Завантажити застосунок можна безплатно, а на сайті є розділ порад для тренерів.', 'MOJO is a one-stop solution for families whose kids play sports and for volunteer coaches. The coaching section offers effective practices that kids love: hundreds of videos and session plans from top experts in sports. Team management simplifies scheduling, attendance tracking, messaging and other organizational tasks. In the FanZone you can score games, live stream matches and save highlights, adding everything to the player''s profile to share with family on any device. MOJO is now a TeamSnap company. The app is free to download, and the site has a Coach''s Corner with tips.', 'Сотні відео й планів тренувань для дітей
Розклад і облік відвідуваності
Повідомлення команді
Рахунок, трансляції й хайлайти
Профіль гравця для родини', 'Hundreds of kid-friendly practice videos and plans
Scheduling and attendance
Team messaging
Scoring, streaming and highlights
Player profile for families', 'Батьки дітей-спортсменів і тренери-волонтери дитячих команд.', 'Parents of young athletes and volunteer youth coaches.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
