-- Momence — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'momence.com' OR LOWER(`name`) = LOWER('Momence'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Momence', NULL, 'https://www.momence.com', NULL, NULL, 'Momence — єдина платформа для студій йоги, пілатесу, танців, сайклу й бутик-фітнесу: розклад, оплати, маркетинг на основі реальної поведінки клієнтів і AI Inbox, що швидко відповідає клієнтам. Є демо для студій.', 'Momence is one platform for yoga, Pilates, dance, indoor cycling and boutique fitness studios: scheduling, payments, marketing based on real client behavior and an AI Inbox that answers clients fast.', 'Momence — це не система бронювання, обвішана розрізненими інструментами, а одна платформа, де розклад, оплати, маркетинг і активність клієнтів пов''язані між собою. Завдяки цьому студії витрачають менше часу на ручну роботу. Рішення розраховане на студії йоги, пілатесу, танців, сайклу, фітнесу та бутик-формати: допомагає заповнювати заняття, повертати клієнтів і спрощувати роботу студії. Маркетинг будується на реальній поведінці клієнтів і працює автоматично в тій самій системі. AI Inbox дає клієнтам швидкі відповіді саме тоді, коли вони готові забронювати, купити щось або змінити запис. Клієнти бронюють і купують заняття через Momence; доступна демонстрація.', 'Momence is not a booking system surrounded by disconnected tools but one platform where scheduling, payments, marketing and customer activity are connected. As a result studios spend less time on manual work. It is built for yoga, Pilates, dance, indoor cycling, fitness and boutique studios: it helps fill classes, bring clients back and make studio life easier. Marketing is based on real client behavior and runs automatically in the same system. The AI Inbox gives customers fast answers right when they are ready to book, buy or make a change. Clients book and buy through Momence, and demos are available.', 'Розклад і бронювання
Оплати й членства
Маркетинг за поведінкою клієнтів
AI Inbox для швидких відповідей
Для студій різних напрямів', 'Scheduling and booking
Payments and memberships
Behavior-based marketing
AI Inbox for fast replies
For many studio types', 'Студії йоги, пілатесу, танців, сайклу та бутик-фітнесу.', 'Yoga, Pilates, dance, indoor cycling and boutique fitness studios.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
