INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Momence is not a booking system surrounded by disconnected tools but one platform where scheduling, payments, marketing and customer activity are connected. As a result studios spend less time on manual work. It is built for yoga, Pilates, dance, indoor cycling, fitness and boutique studios: it helps fill classes, bring clients back and make studio life easier. Marketing is based on real client behavior and runs automatically in the same system. The AI Inbox gives customers fast answers right when they are ready to book, buy or make a change. Clients book and buy through Momence, and demos are available.', 'manual' FROM DUAL WHERE @new = 1;
