-- Muscle & Motion — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'muscleandmotion.com' OR LOWER(`name`) = LOWER('Muscle & Motion'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Muscle & Motion', NULL, 'https://www.muscleandmotion.com', NULL, NULL, 'Muscle & Motion — 3D-застосунки з анатомії й кінезіології: як працюють м''язи в силових вправах, йозі, пілатесі й поставі, онлайн-курси з біомеханіки руху для тренерів, фізіотерапевтів, студентів і атлетів.', 'Muscle & Motion offers 3D anatomy and kinesiology apps showing how muscles work in strength exercises, yoga, Pilates and posture, plus online movement biomechanics courses for trainers, physios, students and athletes.', 'Muscle & Motion допомагає зрозуміти, як рухається тіло, через 3D-візуалізацію анатомії. Лінійка застосунків включає Strength Training (як працюють м''язи у вправах), Anatomy, Posture та Yoga. Онлайн-курси охоплюють анатомію й біомеханіку руху, функціональну анатомію тренувань і роботу з болем у передній частині коліна. Продукти розраховані на фітнес-професіоналів — персональних тренерів, фізіотерапевтів, інструкторів йоги й пілатесу, — на зали й фітнес-центри, атлетів CrossFit і HYROX, відвідувачів залу, а також на студентів кінезіології та спортивної науки й навчальні заклади. Є окремі тарифи для установ, база знань, блог і відповіді на запитання.', 'Muscle & Motion helps you understand how the body moves through 3D anatomy visualization. The app lineup includes Strength Training (how muscles work in exercises), Anatomy, Posture and Yoga. Online courses cover the anatomy and biomechanics of movement, functional training anatomy and anterior knee pain. Products are designed for fitness professionals — personal trainers, physical therapists, yoga and Pilates instructors — for gyms and fitness centers, CrossFit and HYROX athletes, gym-goers, kinesiology and sports science students, and educational institutions. There are institutional plans, a knowledge center, a blog and FAQs.', '3D-анатомія м''язів у вправах
Застосунки Strength, Anatomy, Posture, Yoga
Онлайн-курси з біомеханіки
Рішення для залів і навчальних закладів
База знань', '3D muscle anatomy in exercises
Strength, Anatomy, Posture and Yoga apps
Online biomechanics courses
Solutions for gyms and schools
Knowledge center', 'Персональні тренери, фізіотерапевти, інструктори йоги й пілатесу, студенти та атлети.', 'Personal trainers, physical therapists, yoga and Pilates instructors, students and athletes.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
