-- Noctie — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'noctie.ai' OR LOWER(`name`) = LOWER('Noctie'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Noctie', NULL, 'https://noctie.ai', NULL, NULL, 'Noctie — шаховий AI, що грає як людина вашого рівня: гра проти комп''ютера з оцінкою кожного ходу «людськими» мірками, тренування обраних дебютів, власні позиції й задачі з ваших помилок; 7 днів безплатно, далі 14 EUR.', 'Noctie is a human-like chess AI that plays at your level: play the computer with move-by-move feedback judged like a human, practice chosen openings, custom positions and puzzles from your mistakes; 7 days free, then 14 EUR.', 'Noctie перетворює кожну партію на урок. На відміну від звичайних рушіїв, AI грає як людина саме вашого рівня, тож тренування проти нього схоже на гру з реальним суперником. Після кожного ходу ви миттєво отримуєте кольорову оцінку — від грубої помилки до чудового ходу, — яку визначають за людськими, а не машинними мірками. Можна обрати дебют, який розігруватиме AI, і перевірити себе в найпоширеніших варіантах, а також налаштувати власні позиції та ендшпілі. Зі своїх помилок у партіях Noctie та в імпортованих іграх застосунок створює задачі-флешкарти. Перші 7 днів безплатні, далі підписка коштує 14 EUR на місяць.', 'Noctie turns every game into a lesson. Unlike typical engines, its AI plays like a human at your level, so training against it feels like playing a real opponent. After every move you instantly get a color grade — from blunder to excellent — judged like a human rather than an engine. You can choose which opening the AI plays and test yourself in the most common variations, as well as set up custom positions and endgames. From your mistakes in Noctie games and imported ones, the app creates flashcard puzzles. The first 7 days are free, then the subscription costs 14 EUR per month.', 'AI, що грає як людина вашого рівня
Оцінка кожного ходу
Тренування дебютів
Власні позиції й ендшпілі
Задачі з ваших помилок
7 днів безплатно', 'AI that plays like a human at your level
Feedback on every move
Opening practice
Custom positions and endgames
Puzzles from your mistakes
7 days free', 'Шахісти-аматори, які хочуть тренуватися проти «живого» суперника.', 'Amateur chess players who want to train against a human-like opponent.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
