-- Nolio — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'nolio.io' OR LOWER(`name`) = LOWER('Nolio'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Nolio', NULL, 'https://www.nolio.io', NULL, NULL, 'Nolio — французька платформа для тренерів, клубів і спортсменів: планування тренувань із календарем запланованого й виконаного, конструктор сесій з автовідправкою на годинник, аналіз результатів і маркетплейс планів.', 'Nolio is a French platform for coaches, clubs and athletes: session planning with a planned-vs-completed calendar, a session builder that sends workouts to watches, performance analysis and a plan marketplace.', 'Nolio спрощує щоденну роботу тренерів і спортсменів, передусім у видах спорту на витривалість. Платформа дозволяє планувати сесії, вести календар запланованого та виконаного, використовувати шаблони планів, сесій і вправ. Конструктор структурованих сесій автоматично надсилає тренування на годинник спортсмена, а аналітика допомагає розбирати результати й стежити за прогресом підопічних. Є рішення для тренерів, клубів і самих спортсменів, маркетплейс тренувальних планів, навчальні курси, мастеркласи, вебінари, подкаст Secrets d''Endurance і блог. Тарифи для тренерів починаються від 19,90 EUR на місяць (Starter), тариф Classic включає одного преміум-спортсмена; доступні безплатна пробна версія й демо.', 'Nolio simplifies the daily work of coaches and athletes, especially in endurance sports. The platform lets you plan sessions, keep a planned-versus-completed calendar and use templates for plans, sessions and exercises. The structured session builder automatically sends workouts to the athlete''s watch, and analytics help review results and follow athletes'' progress. There are solutions for coaches, clubs and athletes, a training plan marketplace, training courses, masterclasses, webinars, the Secrets d''Endurance podcast and a blog. Coach plans start at 19.90 EUR per month (Starter), and the Classic plan includes one Premium athlete; a free trial and demo are available.', 'Планування й календар тренувань
Шаблони планів, сесій і вправ
Автовідправка сесій на годинник
Аналіз результатів
Маркетплейс планів
Навчання для тренерів', 'Training planning and calendar
Plan, session and exercise templates
Auto-send sessions to watches
Performance analysis
