SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'omnic.ai' OR LOWER(`name`) = LOWER('Omnic.AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Omnic.AI', NULL, 'https://omnic.ai', NULL, NULL, 'Omnic.AI — віртуальний AI-коуч для кіберспортсменів: Omnic Forge за допомогою комп''ютерного зору й глибинного навчання аналізує відео вашого геймплею, підказує виграшні стратегії й допомагає прокачати навички; безплатно.', 'Omnic.AI is a virtual AI coach for esports players: Omnic Forge uses computer vision and deep learning to analyze your gameplay video, reveal winning strategies and help level up your skills; free.', 'Omnic.AI допомагає гравцям, які мріють про кіберспорт, грати розумніше. Головний інструмент — Omnic Forge: перший у своєму роді AI, що використовує комп''ютерний зір і глибинне навчання для аналізу відео вашого геймплею. Система розбирає ваші дії, допомагає відкривати виграшні стратегії та прокачувати навички, працюючи як віртуальний тренер. Що більшою стає спільнота, то більше Forge знає про гру й то кращі поради дає. Почати можна безплатно, а на сайті є відповіді на часті запитання, інформація про місію, партнерства, спільноту й магазин. Компанія також приділяє увагу різноманіттю та інклюзивності в кіберспорті.', 'Omnic.AI helps aspiring esports players game smarter. Its main tool is Omnic Forge, a first-of-its-kind AI that uses computer vision and deep learning to analyze video of your gameplay. The system breaks down your actions, helps you discover winning strategies and level up your skills, acting as a virtual coach. As the community grows, the Forge learns more about the game and gives better advice. You can start for free, and the site has FAQs, information about the mission, partnerships, the community and a store. The company also focuses on diversity and inclusion in esports.', 'AI-аналіз відео геймплею
