INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Playbook', NULL, 'https://www.playbookapp.io', NULL, NULL, 'Playbook — платформа для фітнес-креаторів, тренерів та інструкторів: власний застосунок за хвилини, підписки на тренування для вашої аудиторії, перевірені схеми утримання й команда, що допомагає рости; старт безплатний.', 'Playbook is a platform for fitness creators, coaches and instructors: launch your own app in minutes, sell workout subscriptions to your audience, use proven retention frameworks and a growth team; free to start.', 'Playbook допомагає фітнес- і велнес-креаторам, тренерам та інструкторам перетворювати аудиторію на регулярний дохід. Платформа дозволяє за кілька хвилин запустити стильний застосунок під власним брендом, де підписники отримують тренування, програми й спільноту. Компанія спирається на дані тисяч креаторів за десятиліття роботи — що саме впливає на кількість підписників, утримання й дохід — і надає ці напрацювання разом із командою, яка допомагає їх втілювати. Модель партнерська: Playbook заробляє лише тоді, коли заробляє креатор. Почати можна безплатно, а на сайті описано функції, історії креаторів і тарифи.', 'Playbook helps fitness and wellness creators, coaches and instructors turn their audience into recurring income. The platform lets you launch a sleek branded app in minutes where subscribers get workouts, programs and a community. The company draws on a decade of data from thousands of creators — what drives subscribers, retention and revenue — and provides that playbook along with a team that runs it with you. The model is aligned: Playbook only makes money when the creator does. It is free to start, and the site describes features, creator stories and pricing.', 'Власний фітнес-застосунок за хвилини
Підписки на тренування для аудиторії
Схеми утримання підписників
Підтримка команди зростання
Безплатний старт', 'Your own fitness app in minutes
Workout subscriptions for your audience
