SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'playvs.com' OR LOWER(`name`) = LOWER('PlayVS'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PlayVS', NULL, 'https://playvs.com', NULL, NULL, 'PlayVS — платформа шкільного й студентського кіберспорту в Північній Америці: змагання для середньої та старшої школи й коледжів, навчання й коучинг гравців, навчальна програма Gaming Concepts і довідник тренера.', 'PlayVS is a scholastic and collegiate esports platform in North America: competitions for middle school, high school and college, player training and coaching, the Gaming Concepts curriculum and a coach handbook.', 'PlayVS допомагає учням і студентам отримувати освітні, соціальні та особисті переваги від змагального гейміну. Платформа організовує кіберспортивні змагання для середньої й старшої школи та коледжів, пропонує тренування й коучинг гравців, а також участь у програмі Special Olympics Unified. Нагороджена навчальна програма Gaming Concepts вибудовує структуровані шляхи в змагальний геймінг для початкової, середньої та старшої школи й включає проєкт портфоліо з геймкастингу. Для шкіл є пошук за штатами, вебінари, рекрутинг, партнерська програма та довідник тренера. PlayVS допомагає школам запускати кіберспортивні програми з нуля.', 'PlayVS helps students unlock the educational, social and personal benefits of competitive gaming. The platform runs esports competitions for middle school, high school and college, offers player training and coaching, and participates in the Special Olympics Unified program. The award-winning Gaming Concepts curriculum builds structured pathways into competitive gaming for elementary, middle and high schools and includes a gamecasting portfolio project. Schools get a state search, webinars, recruitment, a partner program and a coach handbook. PlayVS helps schools launch esports programs from scratch.', 'Шкільні й студентські кіберспортивні ліги
Тренування й коучинг гравців
Навчальна програма Gaming Concepts
Special Olympics Unified
Довідник тренера', 'School and college esports leagues
Player training and coaching
Gaming Concepts curriculum
Special Olympics Unified
Coach handbook', 'Школи, коледжі, тренери з кіберспорту та учні.', 'Schools, colleges, esports coaches and students.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
