SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pushpress.com' OR LOWER(`name`) = LOWER('PushPress'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PushPress', NULL, 'https://www.pushpress.com', NULL, NULL, 'PushPress — ПЗ для управління залом, що росте разом із бізнесом: автоматизація, PushPress AI, система роботи з лідами, відстеження тренувань, брендований застосунок, страхування й інтеграції зі Stripe, Zapier.', 'PushPress is gym management software that scales with your business: automation, PushPress AI, a lead engagement system, workout tracking, a branded app, insurance and integrations with Stripe and Zapier.', 'PushPress допомагає автоматизувати й масштабувати фітнес-бізнес за допомогою простого рішення, яке подобається і клієнтам, і команді. Платформа підходить для кросфіт-залів, шкіл бойових мистецтв, залів силової та функціональної підготовки, малих груп і персонального тренінгу, а також спортивної підготовки. Додаткові продукти включають систему автоматизованої роботи з лідами, щоб перетворювати більше звернень на платних клієнтів, відстеження тренувань для залу, повноцінний застосунок під вашим брендом і гнучкі варіанти страхування для залів. PushPress AI допомагає з рутинними задачами. Є інтеграції з MailChimp, Slack, Stripe, Facebook Ads, Google Analytics, Zapier і сервісами харчування.', 'PushPress helps automate and scale a fitness business with an easy solution that clients and teams love. The platform suits CrossFit gyms, martial arts schools, strength and conditioning gyms, small group and personal training, and sports performance facilities. Add-on products include an automated lead engagement system to convert more leads into paying clients, workout tracking for the gym, a fully built app with your branding and flexible gym insurance options. PushPress AI helps with routine tasks. Integrations include MailChimp, Slack, Stripe, Facebook Ads, Google Analytics, Zapier and nutrition services.', 'Управління залом і білінг
PushPress AI
