SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'refrag.gg' OR LOWER(`name`) = LOWER('Refrag'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Refrag', NULL, 'https://refrag.gg', NULL, NULL, 'Refrag — тренувальна платформа для Counter-Strike 2, що дає ясність тренера, точність тренажера й нове бачення власної гри: допомагає зрозуміти, чому ви програєте, швидше адаптуватися й відчути прогрес навіть за щільного графіка.', 'Refrag is a Counter-Strike 2 training platform that gives you a coach''s clarity, a trainer''s precision and new insight into your game: understand why you lose, adapt faster and feel progress even on a busy schedule.', 'Refrag допомагає гравцям у Counter-Strike 2 грати розумніше. Платформа поєднує розбір гри, як це зробив би тренер, точні тренувальні сценарії, як у спеціальному тренажері, та аналітику, що дозволяє побачити свою гру по-новому. Сервіс допомагає зрозуміти, чому ви програєте раунди й матчі, швидше адаптуватися до різних ситуацій і відчувати реальний прогрес навіть тоді, коли часу на тренування небагато. На сайті пояснено, як усе працює, описано функції й тарифи, а також є блог із порадами. Інтерфейс доступний багатьма мовами, зокрема українською, польською, німецькою, португальською та китайською.', 'Refrag helps Counter-Strike 2 players play smarter. The platform combines game review the way a coach would do it, precise training scenarios like a dedicated trainer and analytics that let you see your game in a new way. It helps you understand why you lose rounds and matches, adapt faster to different situations and feel real progress even when training time is limited. The site explains how it works, the features and pricing, and has a blog with tips. The interface is available in many languages, including Ukrainian, Polish, German, Portuguese and Chinese.', 'Розбір гри як від тренера
Тренувальні сценарії
Аналітика матчів
Швидка адаптація
Українська мова інтерфейсу', 'Coach-style game review
Training scenarios
Match analytics
Faster adaptation
Ukrainian interface', 'Гравці в Counter-Strike 2, які хочуть прогресувати.', 'Counter-Strike 2 players who want to improve.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
