INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Skillest', NULL, 'https://skillest.com', NULL, NULL, 'Skillest — платформа онлайн-коучингу з гольфу: надсилаєте відео свінгу й отримуєте персональний відеоаналіз, вправи та план від власного тренера; також бейсбол, баскетбол, крикет і плавання, інструменти для тренерів.', 'Skillest is an online golf coaching platform: send your swing and get personalized video analysis, drills and a plan from your own coach; also baseball, basketball, cricket and swimming, plus tools for coaches.', 'Skillest виходить з ідеї, що гравцеві потрібен не ще один урок, а постійний тренер. Зустрічі раз на місяць недостатньо, тому платформа дає змогу частіше отримувати зворотний зв''язок: ви записуєте свінг, надсилаєте відео й отримуєте персональний відеоаналіз, вправи та план від свого тренера. Можна переглядати каталог тренерів світового рівня й обрати того, хто підходить. Для тренерів Skillest — спосіб розвивати очний і онлайн-бізнес: більше свободи, доходу й впливу. Окрім гольфу, на платформі є тренери з бейсболу, баскетболу, крикету та плавання, а також курси. Застосунок доступний в App Store і Google Play.', 'Skillest starts from the idea that players don''t need another lesson — they need an ongoing coach. Seeing a coach once a month isn''t enough, so the platform enables more frequent feedback: record your swing, send the video and get personalized video analysis, drills and a plan from your own coach. You can browse a catalog of world-class coaches and choose the right one. For coaches, Skillest is a way to grow in-person and online businesses with more freedom, income and impact. Besides golf there are baseball, basketball, cricket and swimming coaches, plus courses. The app is on the App Store and Google Play.', 'Відеоаналіз свінгу від тренера
Персональні вправи й план
