-- SkillShark — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'skillshark.com' OR LOWER(`name`) = LOWER('SkillShark'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SkillShark', NULL, 'https://skillshark.com', NULL, NULL, 'SkillShark — застосунок для оцінювання спортсменів і проведення відборів: замінює паперові бланки й таблиці, допомагає тренерам швидше й упевненіше ухвалювати рішення та розвивати гравців у десятках видів спорту.', 'SkillShark is an athlete evaluation and tryout app: it replaces paper forms and spreadsheets, helping coaches decide faster and with more confidence and develop players across dozens of sports.', 'SkillShark замінює трудомісткі й схильні до помилок методи оцінювання гравців — папір і таблиці — на застосунок, що спрощує весь процес. Тренери й оцінювачі виставляють оцінки на телефоні чи планшеті під час відборів і тестувань, а система автоматично збирає результати, рахує підсумки й формує звіти для рішень і розвитку гравців. Застосунок підходить для спортивних організацій та академій і підтримує бейсбол, баскетбол, американський футбол, хокей, лакрос, регбі, футбол, софтбол, волейбол і ще кілька десятків видів — від бадмінтону до боротьби. Безплатний тариф Prospect дозволяє оцифрувати процес для 25 гравців; далі ліцензії продаються блоками по 25 гравців.', 'SkillShark replaces time-consuming and error-prone player evaluation methods — paper and spreadsheets — with an app that streamlines the whole process. Coaches and evaluators score players on a phone or tablet during tryouts and testing, and the system automatically collects results, calculates totals and builds reports for decisions and player development. The app suits sports organizations and academies and supports baseball, basketball, football, hockey, lacrosse, rugby, soccer, softball, volleyball and dozens more — from badminton to wrestling. The free Prospect plan digitizes the process for 25 players; after that licenses are sold in blocks of 25 players.', 'Цифрове оцінювання гравців
Відбори й тестування на телефоні
Автоматичні підсумки й звіти
Десятки видів спорту
Безплатний тариф на 25 гравців', 'Digital player evaluations
Tryouts and testing on a phone
Automatic totals and reports
Dozens of sports
Free plan for 25 players', 'Спортивні організації, академії, тренери й оцінювачі, які проводять відбори.', 'Sports organizations, academies, coaches and evaluators running tryouts.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
