SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sporteasy.net' OR LOWER(`name`) = LOWER('SportEasy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportEasy', NULL, 'https://www.sporteasy.net', NULL, NULL, 'SportEasy — застосунок для керування аматорською командою чи клубом: виклики на гру в один клік, спільні календарі, захищений чат, склади, статистика, оплати й реєстрація; безплатний для команд, з тарифами для клубів.', 'SportEasy is an app for managing an amateur team or club: one-click match call-ups, shared calendars, secure messaging, line-ups, stats, payments and registration; free for teams, with plans for clubs.', 'SportEasy — французький сервіс для аматорських команд і спортивних клубів. Для команд є безплатний застосунок: виклики гравців на матч в один клік, спільні календарі, захищений чат, складання складів, розподіл завдань, статистика, онлайн-оплати, ведення чемпіонатів і розділ «після матчу». Для клубів — універсальне ПЗ з онлайн-реєстрацією та оплатами, календарем і плануванням, комунікацією, керуванням групами, командами й членами, спортивною частиною та видимістю для спонсорів. SportEasy підтримує футбол, регбі, баскетбол, гандбол, волейбол, настільний теніс, дзюдо та інші види спорту. Є програми спонсорства, контент, блог і гіди для клубів.', 'SportEasy is a French service for amateur teams and sports clubs. Teams get a free app: one-click match call-ups, shared calendars, secure messaging, line-ups, task management, statistics, online payments, league management and a post-match section. Clubs get all-in-one software with online registration and payments, calendar and planning, communication, group, team and member management, sports management and sponsor visibility. SportEasy supports football, rugby, basketball, handball, volleyball, table tennis, judo and other sports. There are sponsorship programs, content, a blog and guides for clubs.', 'Виклики на гру в один клік
Спільні календарі й чат
Склади й статистика
Онлайн-реєстрація й оплати
ПЗ для клубів
Видимість для спонсорів', 'One-click match call-ups
Shared calendars and chat
Line-ups and stats
Online registration and payments
Club management software
Sponsor visibility', 'Аматорські команди й спортивні клуби, переважно у Франції.', 'Amateur teams and sports clubs, mainly in France.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
