-- SportLoMo — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportlomo.com' OR LOWER(`name`) = LOWER('SportLoMo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportLoMo', NULL, 'https://sportlomo.com', NULL, NULL, 'SportLoMo — єдина платформа для управління всім видом спорту: реєстрація й членства, safeguarding і відповідність правилам, змагання, ігри й судді, події та квитки, оплати, сайти й застосунки для федерацій, ліг і клубів.', 'SportLoMo is one platform to run an entire sport: registration and membership, safeguarding and compliance, competitions, games and officials, events and ticketing, payments, websites and apps for federations, leagues and clubs.', 'SportLoMo — хмарна система, у якій усі рівні спорту — від національного керівного органу до клубів — працюють в одній пов''язаній системі. Модуль реєстрації та членства дозволяє керувати індивідуальними, командними й клубними реєстраціями, перевіряти допуск, safeguarding, медичний дозвіл і правила на кожному рівні. Також платформа охоплює управління й відповідність правилам безпечного спорту, події, турніри й продаж квитків, змагання, ігри та призначення суддів, застосунки й комунікацію, сайти, платежі та фінанси. Рішення розраховане на національні федерації, регіональні асоціації, університети, ліги, турніри та клуби; на сайті є кейси й новини.', 'SportLoMo is a cloud system where every level of a sport — from the national governing body to clubs — works on the same connected system. The registration and membership module manages individual, team and club registrations while enforcing eligibility, safeguarding, medical clearance and governance rules at every level. The platform also covers governance and safe sport compliance, events, tournaments and ticketing, competitions, games and officials, apps and communications, websites, payments and finance. It serves national federations, state associations, universities, leagues, tournaments and clubs, and the site has case studies and news.', 'Реєстрація й членства на всіх рівнях
Safeguarding і відповідність правилам
Змагання, ігри й судді
Події, турніри й квитки
Сайти й застосунки
Платежі й фінанси', 'Registration and membership at every level
Safeguarding and compliance
Competitions, games and officials
Events, tournaments and tickets
Websites and apps
Payments and finance', 'Національні федерації, асоціації, ліги, університети й клуби.', 'National federations, associations, leagues, universities and clubs.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
