SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportsmith.co' OR LOWER(`name`) = LOWER('Sportsmith'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportsmith', NULL, 'https://www.sportsmith.co', NULL, NULL, 'Sportsmith — платформа навчання для фахівців спорту й фітнесу: статті, презентації, звіти про зарплати, конференції й онлайн-симпозіуми, спільнота, а в Premium — інструменти, калькулятори, бібліотека вправ і курси.', 'Sportsmith is a learning platform for sport and fitness professionals: articles, presentations, salary reports, conferences and online symposiums, a community, and in Premium — toolkits, calculators, an exercise library and courses.', 'Sportsmith допомагає фахівцям зі спорту й фітнесу вчитися в провідних практиків. Розділ навчання містить статті, звіти про зарплати та презентації, розділ прослуховування — подкасти, а події включають конференції (наприклад, конференцію зі швидкісної підготовки на «Етіхад Стедіум» у Манчестері), онлайн-симпозіуми та круглі столи. Спільнота пропонує галузеві події, вакансії, зустрічі й групу в WhatsApp. Преміум-доступ відкриває редакційні матеріали, інструментарії, калькулятор зарплат, конспекти подкастів, бібліотеку вправ, калькулятор кондиційної підготовки та курси. Теми охоплюють спритність, кар''єру, кондицію, аналіз даних, жінок-атлеток, профілактику травм, стрибки, лідерство, харчування й періодизацію.', 'Sportsmith helps sport and fitness professionals learn from leading practitioners. The learn section has articles, salary reports and presentations, the listen section has podcasts, and events include conferences (such as a speed training conference at the Etihad Stadium in Manchester), online symposiums and roundtables. The community offers industry events, jobs, meetups and a WhatsApp group. Premium unlocks editorials, toolkits, a salary calculator, podcast summaries, an exercise library, a conditioning calculator and courses. Topics cover agility, career development, conditioning, data analysis, female athletes, injury prevention, jump training, leadership, nutrition and periodization.', 'Статті й презентації експертів
Конференції та симпозіуми
