SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sporttracks.mobi' OR LOWER(`name`) = LOWER('SportTracks'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportTracks', NULL, 'https://sporttracks.mobi', NULL, NULL, 'SportTracks — платформа тренувань для бігу, велоспорту й тріатлону: прогноз результатів, окремі інструменти для пробіжок, заїздів і запливів, планування з синхронізацією календаря, особисті рекорди й режим для тренерів.', 'SportTracks is a training platform for running, cycling and triathlon: performance prediction, separate tools for runs, rides and swims, workout planning with calendar sync, personal records and coaching mode.', 'SportTracks поєднує простий інтерфейс із потужними інструментами для серйозних спортсменів на витривалість. Платформа прогнозує результати на змаганнях, має окремі інструменти для аналізу пробіжок, велозаїздів і запливів, дозволяє планувати тренування з синхронізацією календаря. Можна фільтрувати особисті рекорди за видом спорту й датою, переглядати хронологію рекордів, бачити детальні дані про погоду з можливістю редагування, а також повністю налаштовувати інструменти й макети. Режим для тренерів дозволяє працювати з підопічними. Преміум коштує 59 USD на рік без реклами з гарантією фіксованої ціни, а 45-денний пробний період нічого не списує після завершення.', 'SportTracks combines an intuitive interface with powerful tools for serious endurance athletes. The platform predicts race performance, has separate tools for analyzing runs, bike rides and swims, and lets you plan workouts with calendar sync. You can filter personal records by sport and date, view a personal records timeline, see detailed editable weather data and fully customize tools and layouts. Coaching mode lets coaches work with athletes. Premium costs 59 USD per year, ad-free with a price lock guarantee, and the 45-day trial doesn''t charge you when it ends.', 'Прогноз результатів
Аналіз бігу, вело й плавання
Планування з синхронізацією календаря
