SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sugarwod.com' OR LOWER(`name`) = LOWER('SugarWOD'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SugarWOD', NULL, 'https://www.sugarwod.com', NULL, NULL, 'SugarWOD — програмне забезпечення для кросфіт-боксів, тренерів і атлетів: публікація тренувань, журнал результатів, спільнота, BoxTV для екранів у залі та маркетплейс програм від CompTrain, Mayhem, Invictus.', 'SugarWOD is software for CrossFit boxes, coaches and athletes: workout publishing, results logging, community, BoxTV for gym screens and a program marketplace with CompTrain, Mayhem and Invictus.', 'SugarWOD допомагає залам функціонального тренінгу зміцнювати спільноту, заняття та роботу тренерів. Власники боксів і тренери публікують тренування, а атлети бачать їх у застосунку, записують результати й підтримують одне одного. BoxTV виводить тренування й результати на екрани в залі. У маркетплейсі можна підключити програми від відомих видавців — CompTrain, Mayhem Athlete, Invictus Fitness, OptimizeMe Nutrition, Warmup and Workout. Є навчальний центр, розвиток тренерів, статті з інструкціями й демо програмування. Ціна залежить від кількості атлетів, для великих залів умови обговорюються окремо; доступний безплатний пробний період.', 'SugarWOD helps functional fitness gyms strengthen their community, classes and coaches. Box owners and coaches publish workouts, and athletes see them in the app, log results and cheer each other on. BoxTV puts workouts and results on screens in the gym. The marketplace lets you plug in programs from well-known publishers — CompTrain, Mayhem Athlete, Invictus Fitness, OptimizeMe Nutrition, Warmup and Workout. There is a learning center, coach development, how-to articles and programming demos. Pricing depends on the number of athletes, larger gyms get custom terms, and a free trial is available.', 'Публікація тренувань для атлетів
Журнал результатів і спільнота
BoxTV для екранів у залі
Маркетплейс програм
Розвиток тренерів
Безплатний пробний період', 'Workout publishing for athletes
Results log and community
BoxTV for gym screens
Program marketplace
Coach development
Free trial', 'Власники кросфіт-боксів і залів функціонального тренінгу, тренери та атлети.', 'CrossFit box and functional gym owners, coaches and athletes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
