SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teamer.net' OR LOWER(`name`) = LOWER('Teamer'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Teamer', NULL, 'https://teamer.net', NULL, NULL, 'Teamer — простий застосунок для організаторів спортивних команд: запрошення учасників, повідомлення, відбір складу й облік присутності, створення тренувань, матчів і подій та онлайн-збір оплат; безплатна реєстрація.', 'Teamer is a simple app for sports team organizers: invite members, message them, coordinate selection and attendance, create training, matches and events, and collect payments online; free sign-up.', 'Teamer створено для всіх, хто організовує спортивну команду та збирає оплати онлайн, — тренерів, менеджерів і капітанів, які хочуть заощадити час. Ви запрошуєте учасників до команди, надсилаєте повідомлення через застосунок, координуєте відбір складу й облік присутності. Можна створювати командні події — тренування, матчі, соціальні заходи — і запрошувати на кожну з них. Учасники отримують зручний застосунок, де в одному місці зібрані повідомлення, події та платежі. Онлайн-збір оплат позбавляє від готівки й нагадувань вручну. Зареєструватися можна безплатно й одразу отримати доступ. Застосунок підходить і для невеликих аматорських команд, і для клубів із кількома складами.', 'Teamer is built for anyone organizing a sports team and collecting payments online — coaches, team managers and captains who want to save time. You invite members to the team, send messages through the app and coordinate team selection and attendance. You can create team events — training sessions, matches, social events — and invite members to each. Members get an easy app with messages, events and payments in one place. Online payment collection removes cash and manual reminders. Sign-up is free with instant access. The app suits both small amateur teams and clubs with several squads.', 'Запрошення й керування учасниками
Повідомлення в застосунку
Відбір складу й присутність
Тренування, матчі й події
Онлайн-збір оплат
Безплатна реєстрація', 'Invite and manage members
In-app messaging
Selection and attendance
Training, matches and events
Online payment collection
Free sign-up', 'Тренери, менеджери й капітани аматорських команд.', 'Coaches, managers and captains of amateur teams.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
