SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teamgenius.com' OR LOWER(`name`) = LOWER('TeamGenius'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TeamGenius', NULL, 'https://teamgenius.com', NULL, NULL, 'TeamGenius — ПЗ для оцінювання гравців на відборах, у таборах і для зворотного зв''язку в 20 видах спорту: без паперових бланків і таблиць, оцінювання тренерів і суддів, комбайни, інтеграції з SportsEngine і TeamSnap.', 'TeamGenius is player evaluation software for tryouts, camps and feedback across 20 sports: no paper forms or spreadsheets, coach and referee evaluations, combines, and integrations with SportsEngine and TeamSnap.', 'TeamGenius — гнучке програмне забезпечення для оцінювання гравців, яке економить час, допомагає ухвалювати кращі рішення й розвивати спортсменів. Воно позбавляє від паперових форм, годин введення даних і складних таблиць під час відборів і таборів. Оцінювачі виставляють бали в застосунку, а система миттєво формує результати. Підтримуються бейсбол, баскетбол, американський футбол, хокей, лакрос, ринґет, футбол, софтбол, волейбол та інші види, а також оцінювання тренерів і суддів та комбайни. До тарифів входять необмежені оцінювання, оцінювачі й адміністратори, бібліотека шаблонів, реєстрація й оплати, інтеграції зі SportsEngine, LeagueApps і TeamSnap. Є 14-денна безплатна версія до 20 гравців.', 'TeamGenius is flexible player evaluation software that saves time, helps make better decisions and develops athletes. It eliminates messy paper forms, hours of data entry and complicated spreadsheets during tryouts and camps. Evaluators score in the app and the system produces results instantly. It supports baseball, basketball, football, hockey, lacrosse, ringette, soccer, softball, volleyball and more, as well as coach and referee evaluations and combines. Plans include unlimited evaluations, evaluators and admins, a template library, registration and payments, and integrations with SportsEngine, LeagueApps and TeamSnap. There is a 14-day free trial for up to 20 players.', 'Оцінювання гравців на відборах
Бібліотека шаблонів
Оцінювання тренерів і суддів
Комбайни
Інтеграції зі SportsEngine, LeagueApps, TeamSnap
14 днів безплатно', 'Player evaluations at tryouts
Template library
Coach and referee evaluations
Combines
SportsEngine, LeagueApps, TeamSnap integrations
14 days free', 'Клуби, асоціації й ліги, що проводять відбори й табори.', 'Clubs, associations and leagues running tryouts and camps.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
