SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teamlinkt.com' OR LOWER(`name`) = LOWER('TeamLinkt'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TeamLinkt', NULL, 'https://teamlinkt.com', NULL, NULL, 'TeamLinkt — проста платформа для дитячих спортивних організацій: реєстрація, розклад і комунікація в одному місці без підписки — TeamLinkt Core безплатний, а оплата стягується лише з платежів, які ви збираєте.', 'TeamLinkt is an easy platform for youth sports organizations: registration, scheduling and communication in one place with no subscription — TeamLinkt Core is free and you only pay a rate on payments you collect.', 'TeamLinkt бере на себе щоденну рутину спортивних організацій, щоб ті могли проводити кращі сезони, будувати сильніші спільноти та дарувати родинам кращий досвід. Платформа об''єднує реєстрацію, розклад і комунікацію, а мобільний застосунок тримає команди й батьків на зв''язку. Головна особливість — модель без підписки: базова версія TeamLinkt Core безплатна для всієї організації, без щомісячних планів, оплати за гравця й річних контрактів; ви сплачуєте лише невелику ставку з платежів, які збираєте через систему. Додаткові модулі підключаються за бажанням. Для організацій, що переходять з інших платформ, діють спеціальні пропозиції; можна замовити демонстрацію.', 'TeamLinkt takes care of the day-to-day work behind the scenes so sports organizations can deliver better seasons, stronger communities and better experiences for families. The platform unifies registration, scheduling and communication, and the mobile app keeps teams and parents connected. Its key feature is a no-subscription model: TeamLinkt Core is free for the whole organization, with no monthly plans, per-player fees or annual contracts; you only pay a small rate on payments collected through the system. Add-ons are optional. Organizations switching from other platforms get special offers, and demos are available.', 'Реєстрація й платежі
Розклад ігор і тренувань
