INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Techne Futbol helps soccer players train on their own between team sessions. Every week the app delivers drills rooted in fundamentals, and coaches show how to do them in videos. As players train they progress through the Sock System and earn real training socks, while live leaderboards show who is training with Techne around the world. Players can choose Techne PRO, a complete guide to self-training, or Fundamentals for beginners. Clubs and teams can give players access and track progress; there are solutions for ODP programs and schools. The first 7 days are free.', 'manual' FROM DUAL WHERE @new = 1;
