SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'thecoachingmanual.com' OR LOWER(`name`) = LOWER('The Coaching Manual'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'The Coaching Manual', NULL, 'https://www.thecoachingmanual.com', NULL, NULL, 'The Coaching Manual — платформа футбольної тренерської освіти: тисячі готових тренувальних сесій, планувальник занять, тижневі й сезонні плани, передсезонні програми, керування клубом і командою, застосунки iOS та Android.', 'The Coaching Manual is a football coaching education platform: thousands of ready-made sessions, a session planner, weekly and season plans, pre-season programs, club and team management and iOS and Android apps.', 'The Coaching Manual прагне зробити якісний футбольний коучинг простим і доступним для кожного — і для новачків, і для досвідчених тренерів. Платформа містить тисячі повноцінних тренувальних сесій, планувальник занять, тижневі плани, ретельно підібрані так, щоб навчати потрібному на кожному етапі розвитку гравців, сезонні та готові передсезонні плани, гід до нового сезону й папки для організації матеріалів. Є інструменти керування клубом і командою та застосунки для iOS і Android. Рішення розраховане на тренерів, клуби, директорів з підготовки та керівні органи; також доступні очне навчання, цифровий асистент і табори.', 'The Coaching Manual aims to make great football coaching easy and accessible for everyone, whether you are just starting out or have been coaching for years. The platform contains thousands of full coaching sessions, a session planner, weekly plans carefully curated to teach the right things at the right stage of player development, season plans and ready-made pre-season plans, a new season guide and folders for organizing material. There are club and team management tools and apps for iOS and Android. It serves coaches, clubs, directors of coaching and governing bodies, with in-person education, a digital assistant and camps also available.', 'Тисячі готових тренувальних сесій
