iOS and Android apps', 'Футбольні тренери, клуби, директори з підготовки та федерації.', 'Football coaches, clubs, directors of coaching and governing bodies.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
