SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tracklete.io' OR LOWER(`name`) = LOWER('Tracklete'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Tracklete', NULL, 'https://tracklete.io', NULL, NULL, 'Tracklete — платформа для веслувальників, команд і клубів: планування тренувань, моніторинг здоров''я атлетів, аналіз ергометра, результатів гонок, GPS і пульсу та командна комунікація з відео й сповіщеннями.', 'Tracklete is a platform for rowers, teams and clubs: training planning, athlete health monitoring, analysis of erg scores, race times, GPS and heart rate data, and team communication with videos and notifications.', 'Tracklete допомагає керувати веслувальниками, командами й клубами за принципом «тренуйся, відстежуй, перемагай». Платформа оптимізує розклад тренувань з урахуванням даних про продуктивність і здоров''я, щоб покращувати результати й уникати травм. Це центр для планування розкладів, моніторингу здоров''я атлетів і відстеження продуктивності: аналізуються результати на ергометрі, час у гонках, дані GPS і пульсу. Командна комунікація дозволяє публікувати розклади, коментарі та тренувальні відео для товаришів по команді чи тренерів і отримувати миттєві сповіщення. Tracklete економить час тренерів і допомагає залишатися на зв''язку з командою; на сайті є тарифи та блог.', 'Tracklete helps manage rowing athletes, teams and clubs on a train-track-win principle. The platform optimizes training schedules with performance and health data to boost results and avoid injuries. It is a hub for planning schedules, monitoring athlete health and tracking performance: ergometer scores, race times, GPS and heart rate data are analyzed. Team communication lets you post schedules, comments and training videos for teammates or coaches and get instant notifications. Tracklete saves coaches time and keeps the team connected; the site has pricing and a blog.', 'Планування тренувань
Моніторинг здоров''я атлетів
Аналіз ергометра, гонок, GPS і пульсу
Командна комунікація
Тренувальні відео й сповіщення', 'Training planning
Athlete health monitoring
Erg, race, GPS and heart rate analysis
Team communication
Training videos and notifications', 'Веслувальники, тренери й веслувальні клуби.', 'Rowers, coaches and rowing clubs.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
