SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainerfu.com' OR LOWER(`name`) = LOWER('Trainerfu'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Trainerfu', NULL, 'https://www.trainerfu.com', NULL, NULL, 'Trainerfu — просте ПЗ для персональних тренерів очно й онлайн: конструктор тренувань, відстеження прогресу, залучення клієнтів, звички, автоматизація, продаж програм, команди та брендований застосунок для iOS і Android.', 'Trainerfu is simple personal trainer software for in-person and online training: a workout builder, progress tracking, client engagement, habits, automation, program sales, teams and a branded iOS and Android app.', 'Trainerfu допомагає персональним тренерам створювати тренування, відстежувати прогрес, продавати програми, залучати клієнтів і розвивати фітнес-бізнес. Платформа включає конструктор тренувань, трекінг результатів, інструменти залучення й звичок, автоматизацію, продаж програм і роботу з командами. Клієнти можуть публікувати фото прогресу й повідомлення, а тренер бачить, що вони роблять між зустрічами. Тарифи розраховані від окремого тренера на 10 клієнтів до залів на 250 клієнтів і корпоративних рішень. За додаткову плату від 75 USD на місяць команда розробить брендований застосунок для iOS і Android. Є 14 днів безплатно, без контрактів і зі скасуванням в один клік.', 'Trainerfu helps personal trainers build workouts, track progress, sell programs, engage clients and grow their fitness business. The platform includes a workout builder, progress tracking, engagement and habit tools, automation, program sales and team features. Clients can post progress photos and messages, and the trainer sees what they do between sessions. Plans range from a solo trainer with 10 clients to gyms with 250 clients and enterprise solutions. For an add-on from 75 USD per month, the team builds a branded iOS and Android app. There is a 14-day free trial, no contracts and one-click cancellation.', 'Конструктор тренувань
Відстеження прогресу
Звички й залучення клієнтів
Продаж програм
Тарифи від тренера до залу
Брендований застосунок', 'Workout builder
Progress tracking
Habits and client engagement
Program sales
Plans from trainer to gym
Branded app', 'Персональні тренери, студії та зали.', 'Personal trainers, studios and gyms.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
