SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trophi.ai' OR LOWER(`name`) = LOWER('trophi.ai'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'trophi.ai', NULL, 'https://www.trophi.ai', NULL, NULL, 'trophi.ai — AI-коучинг у реальному часі для сімрейсингу: голосовий тренер Mansell підказує на кожному повороті, аналіз навичок показує, де ви втрачаєте час, а телеметрія порівнює ваші траси з експертними.', 'trophi.ai offers real-time AI coaching for sim racing: the Mansell voice coach guides you through every corner, skill analysis shows where you lose time, and telemetry compares your traces with an expert''s.', 'trophi.ai розвиває AI, що ставить експертне судження поруч із кожним, хто навчається, у реальному часі. Перевірено цей підхід на понад 10 мільйонах сесій у сімрейсингу. Застосунок для сімрейсерів пропонує голосового тренера Mansell, який веде вас через кожен поворот, аналіз навичок, що точно показує, де втрачається час, живу телеметрію з вашими трасами поряд з експертними та професійну телеметрію для поглибленого аналізу. Доступні різні тарифи, які можна порівняти на сайті. Ту саму технологію під назвою Kairos компанія пропонує бізнесу — для підготовки пілотів, операторів дронів і фахівців нафтогазової галузі.', 'trophi.ai builds AI that puts expert judgment beside every learner in real time. The approach has been proven across 10M+ sim racing sessions. The sim racing app offers the Mansell voice coach that talks you through every corner, skill analysis that shows exactly where you lose time, live telemetry with your traces alongside the expert''s, and pro telemetry for deeper analysis. Several plans are available and can be compared on the site. The company offers the same technology, called Kairos, to businesses — for training pilots, drone operators and oil and gas specialists.', 'Голосовий тренер Mansell у реальному часі
Аналіз навичок і втрат часу
Жива телеметрія поруч з експертом
Професійна телеметрія
Перевірено на 10 млн+ сесій', 'Mansell real-time voice coach
Skill and time-loss analysis
Live telemetry next to an expert
Pro telemetry
Proven on 10M+ sessions', 'Сімрейсери, які хочуть швидше проходити кола й покращувати навички пілотування.', 'Sim racers who want faster laps and better driving skills.', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
