SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'business.virtuagym.com' OR LOWER(`name`) = LOWER('Virtuagym'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Virtuagym', NULL, 'https://business.virtuagym.com', NULL, NULL, 'Virtuagym — ПЗ для залів, студій, персональних тренерів і мереж: членства, персонал, доступ 24/7, бронювання, вебмагазин, а також коучинг клієнтів — конструктор тренувань, харчування, відео на вимогу, пульс.', 'Virtuagym is software for gyms, studios, personal trainers and chains: memberships, staff, 24/7 access, booking, a webshop, plus client coaching — a workout plan creator, nutrition, on-demand video and heart rate.', 'Virtuagym поєднує управління бізнесом, коучинг і залучення клієнтів. Для керування є управління членствами й персоналом, система доступу до залу 24/7, чек-ін для студій, розширена аналітика, керування кількома клубами, вебмагазин і каса. Бронювання охоплює розклад, групові заняття, індивідуальні зустрічі, онлайн-запис на пробне заняття та кредитну систему. Для коучингу клієнтів є конструктор планів тренувань, коучинг харчування, відео на вимогу, відстеження прогресу та тренування за пульсом. Рішення розраховане на зали, фітнес-студії, персональних тренерів, бокс і бойові мистецтва, сайкл, йогу й пілатес, а також на мережі, франшизи та корпоративний велнес. Є безплатна демонстрація й пробний період.', 'Virtuagym combines business management, coaching and engagement. For management there is membership and staff management, a 24/7 gym access system, studio check-in, advanced analytics, multi-club management and a webshop with POS. Booking covers scheduling, group classes, 1-1 appointments, online trial booking and a credit system. For coaching there is a workout plan creator, nutrition coaching, on-demand videos, progress tracking and heart-rate coaching. It serves gyms, fitness studios, personal trainers, boxing and martial arts, indoor cycling, yoga and Pilates, as well as chains, franchises and corporate wellness. A free demo and trial are available.', 'Членства, персонал і аналітика
Доступ 24/7 і чек-ін
Бронювання й кредитна система
Конструктор тренувань і харчування
Відео на вимогу й прогрес
Керування мережею клубів', 'Memberships, staff and analytics
