SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hellowalla.com' OR LOWER(`name`) = LOWER('Walla'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Walla', NULL, 'https://www.hellowalla.com', NULL, NULL, 'Walla — ПЗ для бутик-фітнес-студій із вбудованими AI-автоматизаціями: йога, пілатес, барре, лагрі, сайкл, HIIT; керування студією, брендований застосунок, сайти, утримання клієнтів і прогнози WallaPredict.', 'Walla is boutique fitness studio software with built-in AI automations: yoga, Pilates, barre, Lagree, cycling, HIIT; studio management, a branded app, websites, client retention and WallaPredict forecasts.', 'Walla поєднує AI-управління з реальним досвідом індустрії, щоб студії працювали так, як хоче власник. Компанія позиціонує себе як партнера, що дає впевненість на основі даних для масштабування бутик-фітнес-бізнесу. Рішення розраховане на студії йоги, пілатесу, барре, лагрі, сайклу, кругових тренувань і HIIT, а також франшизи й мережі. Функції охоплюють клієнтський досвід, керування студією, звіти, продажі й маркетинг, брендований застосунок, власні сайти, утримання клієнтів, інтеграції та страхування. У кожному тарифі — необмежена кількість користувачів, аналітика утримання WallaPredict і підтримка живих людей; базовий тариф Core коштує 299 USD на місяць за локацію.', 'Walla merges AI-powered management with real-world studio expertise so studios run the way owners want. The company positions itself as a partner that provides data-backed confidence to scale a boutique fitness business. It is built for yoga, Pilates, barre, Lagree, indoor cycling, circuit training and HIIT studios, as well as franchises and multi-location businesses. Features cover client experience, studio management, reporting, sales and marketing, a branded app, custom websites, client retention, integrations and insurance. Every plan includes unlimited users, WallaPredict retention intelligence and real human support; the Core plan costs 299 USD per month per location.', 'AI-автоматизації для студій
Брендований застосунок і сайти
Прогнози утримання WallaPredict
Звіти, продажі й маркетинг
Необмежена кількість користувачів', 'AI automations for studios
