SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wodify.com' OR LOWER(`name`) = LOWER('Wodify'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wodify', NULL, 'https://www.wodify.com', NULL, NULL, 'Wodify — платформа для залів функціонального тренінгу: операційне управління, маркетингова автоматизація й AI-інструменти, система відстеження тренувань, брендований застосунок, доступ 24/7 і моніторинг пульсу.', 'Wodify is a platform for functional fitness gyms: operations management, marketing automation and AI tools, a workout tracking system, a branded app, 24/7 access and live heart-rate monitoring.', 'Wodify об''єднує в одному місці ключові інструменти для управління залом, маркетингову автоматизацію та застосунок, який можна налаштувати під свій бренд. Окрема гордість — система відстеження результатів тренувань для атлетів. Додаткові модулі включають власний брендований застосунок в App Store, сайти, що краще знаходяться в Google й приводять ліди, контроль доступу 24/7 із керуванням, хто й коли заходить до закладу, маркетплейс тренувальних програм, інтегрований у платформу, а також вбудований моніторинг пульсу з трансляцією в реальному часі. Є AI-інструменти та інтеграції з QuickBooks, Facebook Leads, Slack та іншими сервісами.', 'Wodify brings core gym operations tools, marketing automations and a customizable app into one place. A highlight is its performance tracking system for athletes'' workouts. Add-ons include your own branded app in the App Store, custom websites that rank better on Google and bring leads, 24/7 access control over who enters the facility and when, a workout marketplace fully integrated into the platform, and built-in live-streamed heart-rate monitoring. There are AI tools and integrations with QuickBooks, Facebook Leads, Slack and other services.', 'Операційне управління залом
