-- Zen Planner — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zenplanner.com' OR LOWER(`name`) = LOWER('Zen Planner'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Zen Planner', NULL, 'https://www.zenplanner.com', NULL, NULL, 'Zen Planner — універсальне ПЗ для управління залом від Daxko: менше адміністрування, більше тренерської роботи й сильніша спільнота; членства, розклад, оплати, а платите лише за активних учасників. Є демо.', 'Zen Planner is all-in-one gym management software from Daxko: less admin, more coaching and a stronger community; memberships, scheduling and payments, and you only pay for active members.', 'Zen Planner — програмне забезпечення для всього фітнес-бізнесу, що спрощує операційну роботу, підвищує залученість учасників і допомагає залу зростати. Ідея — менше адміністрування, більше тренерської роботи й сильніша спільнота. Платформа Zen Planner Studio дозволяє керувати членствами, розкладом, оплатами та іншими процесами в одній системі. Модель ціноутворення побудована навколо реального зростання залу: ви платите лише за активних учасників, а потенційні клієнти й персонал не тарифікуються. Компанія належить Daxko, пропонує демо, допомогу з переходом з інших систем і порівняння з Mindbody, Gymdesk та Kicksite.', 'Zen Planner is software for the entire fitness business that simplifies operations, boosts member engagement and helps gyms grow. The idea is less admin, more coaching and a stronger community. The Zen Planner Studio platform manages memberships, scheduling, payments and other processes in one system. Pricing is built around how gyms actually grow: you only pay for active members, with no charges for prospects or staff. The company is part of Daxko and offers demos, help switching from other systems and comparisons with Mindbody, Gymdesk and Kicksite.', 'Управління членствами
Розклад і бронювання
Оплати
Оплата лише за активних учасників
Допомога з переходом з інших систем', 'Membership management
Scheduling and booking
Payments
Pay only for active members
Help switching from other systems', 'Фітнес-зали, кросфіт-бокси, школи бойових мистецтв і студії.', 'Fitness gyms, CrossFit boxes, martial arts schools and studios.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
